(window.NTDATA=window.NTDATA||{});(NTDATA.arar=NTDATA.arar||{}).mt={"1":{"1":"Աբրահամի որդի Դավթի որդի Հիսուս Քրիստոսի ծննդաբանությունը։","2":"Աբրահամը ծնեց Իսահակին, Իսահակը ծնեց Հակոբին, Հակոբը ծնեց Հուդային ու նրա եղբայրներին.","3":"Հուդան ծնեց Փարեսին ու Զարային՝ Թամարից. Փարեսը ծնեց Եսրոնին. Եսրոնը ծնեց Արամին.","4":"Արամը ծնեց Ամինադաբին. Ամինադաբը ծնեց Նաասոնին. Նաասոնը ծնեց Սաղմոնին.","5":"Սաղմոնը ծնեց Բոոսին՝ Ռախաբից. Բոոսը ծնեց Ովբեդին՝ Հռութից. Ովբեդը ծնեց Հեսսեին. Հեսսեն ծնեց Դավիթ թագավորին։","6":"Դավիթ թագավորը ծնեց Սողոմոնին՝ Ուրիայի կնոջից.","7":"Սողոմոնը ծնեց Ռոբովամին. Ռոբովամը ծնեց Աբիային. Աբիան ծնեց Ասային.","8":"Ասան ծնեց Հովսափատին. Հովսափատը ծնեց Հովրամին.","9":"Հովրամը ծնեց Ոզիային. Ոզիան ծնեց Հովաթամին. Հովաթամը ծնեց Աքազին. Աքազը ծնեց Եզեկիային.","10":"Եզեկիան ծնեց Մանասեին. Մանասեն ծնեց Ամոնին. Ամոնը ծնեց Հովսիային։","11":"Հովսիան ծնեց Հեքոնիային ու նրա եղբայրներին՝ Բաբելոնի գերության ժամանակ։","12":"Բաբելոնի գերությունից հետո Հեքոնիան ծնեց Սաղաթիելին. Սաղաթիելը ծնեց Զորաբաբելին.","13":"Զորաբաբելը ծնեց Աբիուդին. Աբիուդը ծնեց Եղիակիմին. Եղիակիմը ծնեց Ազովրին.","14":"Ազովրը ծնեց Սադովկին. Սադովկը ծնեց Աքինին.","15":"Աքինը ծնեց Եղիուդին. Եղիուդը ծնեց Եղիազարին. Եղիազարը ծնեց Մատթանին. Մատթանը ծնեց Հակոբին.","16":"Հակոբը ծնեց Հովսեփին՝ Մարիամի ամուսնուն, որից ծնվեց Հիսուսը, որին Քրիստոս են ասում։","17":"Արդ, Աբրահամից մինչև Դավիթ բոլոր սերունդները տասնչորսն են, Դավթից մինչև բաբելոնյան գերությունը՝ տասնչորս սերունդ, և բաբելոնյան գերությունից մինչև Քրիստոս՝ տասնչորս սերունդ։","18":"Հիսուս Քրիստոսի ծնունդն այսպես եղավ։ Նրա մայրը՝ Մարիամը, Հովսեփի հետ նշանված էր։ Նախքան նրանց՝ միմյանց մերձենալը Մարիամը հղիացավ Սուրբ Հոգուց։","19":"Նրա ամուսինը՝ Հովսեփը, որ արդար էր և չէր ցանկանում նրան խայտառակել, մտածեց գաղտնի արձակել նրան։","20":"Եվ մինչ նա այս մասին էր խորհում, ահա Տիրոջ հրեշտակը երազում հայտնվեց նրան ու ասաց. «Հովսե՛փ, Դավթի՛ որդի, մի՛ վախեցիր քեզ մոտ առնել քո կնոջը՝ Մարիամին, որովհետև նրա մեջ ծնունդ առածը Սուրբ Հոգուց է։","21":"Նա որդի պիտի ծնի, և նրա անունը Հիսուս պիտի դնես, որովհետև նա իր ժողովրդին պիտի փրկի իր մեղքերից»։","22":"Այս ամենը եղավ, որպեսզի իրականանար Տիրոջ կողմից մարգարեի միջոցով ասվածը.","23":"«Ահա կույսը կհղիանա և որդի կծնի, և նրան կկոչեն Էմմանուել» (Ես. 7.14), որ նշանակում է «Աստված մեզ հետ»։","24":"Եվ Հովսեփը, քնից արթնանալով, արեց այնպես, ինչպես Տիրոջ հրեշտակը հրամայեց իրեն, և իր կնոջն իր մոտ առավ։","25":"Եվ նրան չմերձեցավ, մինչև նա ծնեց իր անդրանիկ որդուն, և նրա անունը Հիսուս դրեց։"},"2":{"1":"Երբ Հիսուսը ծնվեց Հրեաստանի Բեթլեհեմ քաղաքում Հերովդեսի թագավորության օրոք, ահա արևելքից մոգեր եկան Երուսաղեմ","2":"և ասացին. «Որտե՞ղ է հրեաների նոր ծնված թագավորը, որովհետև նրա աստղը տեսանք արևելքում ու եկանք նրան երկրպագելու»։","3":"Երբ Հերովդես թագավորը լսեց, վրդովվեց, և նրա հետ՝ ամբողջ Երուսաղեմը։","4":"Նա, իր մոտ հավաքելով բոլոր քահանայապետներին ու ժողովրդի դպիրներին, հարցրեց, թե որտե՛ղ էր ծնվելու Քրիստոսը։","5":"Նրանք պատասխանեցին. «Հրեաստանի Բեթլեհեմում, որովհետև մարգարեի կողմից այսպես է գրված.","6":"\"Եվ դու, Բեթղեհե՛մ, Հուդայի՛ երկիր, բնավ ամենափոքրը չես Հուդայի իշխանների մեջ, քանի որ քեզանից իշխան պիտի ելնի, որը հովվելու է իմ ժողովրդին՝ Իսրայելին\" (Միք. 5.2)»։","7":"Այդ ժամանակ Հերովդեսը, գաղտնի կանչելով մոգերին, նրանցից ճշտեց աստղի երևալու ժամանակը։","8":"Ապա նրանց Բեթլեհեմ ուղարկելով՝ ասաց. «Գնացե՛ք, ստույգ տեղեկացե՛ք երեխայի մասին և երբ գտնեք, հայտնե՛ք ինձ, որպեսզի ես էլ գամ երկրպագեմ նրան»։","9":"Նրանք թագավորին լսելուց հետո գնացին։ Եվ ահա այն աստղը, որ տեսել էին արևելքում, առաջնորդեց նրանց, մինչև որ եկավ և կանգնեց այն տեղի վրա, որտեղ երեխան էր։","10":"Երբ այն աստղը տեսան, շատ ուրախացան։","11":"Երբ տուն մտան, տեսան երեխային իր մոր՝ Մարիամի հետ և գետնին ընկնելով՝ երկրպագեցին նրան։ Եվ բացեցին իրենց գանձերը, նրան ընծաներ մատուցեցին՝ ոսկի, կնդրուկ և զմուռս։","12":"Նրանք, երազում Հերովդեսի մոտ չվերադառնալու հրաման ստանալով, ուրիշ ճանապարհով գնացին իրենց երկիրը։","13":"Երբ նրանք այնտեղից հեռացան, ահա Տիրոջ հրեշտակը երազում հայտնվեց Հովսեփին ու ասաց. «Վե՛ր կաց, վերցրո՛ւ երեխային ու նրա մորը և փախի՛ր Եգիպտոս. այնտեղ մնա՛, մինչև քեզ ասեմ, որովհետև Հերովդեսը փնտրելու է երեխային, որ նրան սպանի»։","14":"Հովսեփը վեր կացավ, գիշերով վերցրեց երեխային ու նրա մորը և մեկնեց Եգիպտոս։","15":"Նա այնտեղ մնաց մինչև Հերովդեսի վախճանը, որպեսզի իրականանար Տիրոջ կողմից մարգարեի միջոցով ասվածը. «Եգիպտոսից իմ որդուն կանչեցի» (Ովս. 11.1)։","16":"Այդ ժամանակ Հերովդեսը, տեսնելով, որ մոգերից խաբվել է, խիստ զայրացավ։ Նա մարդ ուղարկեց՝ կոտորելու Բեթլեհեմում և նրա սահմաններում գտնվող երկու տարեկան ու ավելի փոքր բոլոր երեխաներին՝ ըստ այն ժամանակի, որ ճշտել էր մոգերից։","17":"Այդ ժամանակ իրականացավ Երեմիա մարգարեի միջոցով ասվածը.","18":"«Ռամայում ձայն լսվեց, ողբ ու սաստիկ լացուկոծ. Ռաքելը լալիս էր իր զավակների վրա ու չէր ուզում մխիթարվել, որովհետև նրանք չկային» (Երմ. 31.15)։","19":"Երբ Հերովդեսը մեռավ, ահա Տիրոջ հրեշտակը Եգիպտոսում երազի մեջ հայտնվեց Հովսեփին","20":"ու ասաց. «Վե՛ր կաց, վերցրո՛ւ երեխային ու նրա մորը և գնա՛ Իսրայելի երկիրը, որովհետև երեխայի կյանքն առնել ցանկացողները մեռել են»։","21":"Հովսեփը վեր կացավ, վերցրեց երեխային ու նրա մորը և եկավ Իսրայելի երկիրը։","22":"Երբ լսեց, որ Հրեաստանի վրա Արքեղայոսն է թագավորում իր հոր՝ Հերովդեսի փոխարեն, վախեցավ այնտեղ գնալ և երազում հրաման ստանալով՝ գնաց Գալիլեայի կողմերը։","23":"Եվ եկավ բնակվելու Նազարեթ կոչվող քաղաքում, որպեսզի իրականանար մարգարեների միջոցով ասվածը, թե Նազովրեցի է կոչվելու։"},"3":{"1":"Այն օրերին հայտնվեց Հովհաննես Մկրտիչը, որ քարոզում էր Հրեաստանի անապատում","2":"և ասում. «Ապաշխարե՛ք, որովհետև երկնքի արքայությունը մոտեցել է»։","3":"Սա նա է, ում մասին ասվել է Եսայի մարգարեի միջոցով. «Անապատում կանչողի ձայնն է. \"Պատրաստե՛ք Տիրոջ ճանապարհը, ուղի՛ղ արեք նրա շավիղները\"» (Ես. 40.3)։","4":"Եվ ինքը՝ Հովհաննեսը, ուղտի բրդից հագուստ ուներ և մեջքին՝ կաշվե գոտի։ Նրա կերակուրը մորեխ ու վայրի մեղր էր։","5":"Այդ ժամանակ նրա մոտ էին գնում Երուսաղեմի, ամբողջ Հրեաստանի և Հորդանանի ողջ շրջակայքի բնակիչները։","6":"Եվ նրա ձեռքով մկրտվում էին Հորդանանում և խոստովանում իրենց մեղքերը։","7":"Երբ Հովհաննեսը տեսավ, որ փարիսեցիներից և սադուկեցիներից շատերն են եկել իր մոտ՝ մկրտությունը տեսնելու, նրանց ասաց. «Իժի՛ ծնունդներ, ո՞վ ձեզ զգուշացրեց փախչել գալիք բարկությունից։","8":"Արդ ապաշխարության արժանի արդյո՛ւնք տվեք։","9":"Եվ մի՛ փորձեք ինքներդ ձեզ ասել. \"Մենք որպես հայր ունենք Աբրահամին\", որովհետև ասում եմ ձեզ, որ Աստված Աբրահամի համար կարող է նաև այս քարերից որդիներ ստեղծել։","10":"Կացինն արդեն ծառերի արմատին է մոտեցել. արդ, ամեն ծառ, որ բարի պտուղ չի տալիս, կտրվում ու կրակի մեջ է գցվում։","11":"Ես ձեզ մկրտում եմ ջրով՝ ապաշխարության համար, բայց նա, ով գալիս է իմ հետևից, ինձանից զորավոր է. ես արժանի չեմ անգամ նրա կոշիկները բռնելու։ Նա կմկրտի ձեզ Սուրբ Հոգով ու հրով։","12":"Հոսելին նրա ձեռքում է. նա՛ կմաքրի իր կալը, ցորենը շտեմարանի մեջ կհավաքի, իսկ հարդը կայրի անշեջ հրով»։","13":"Այդ ժամանակ Հիսուսը Գալիլեայից եկավ Հորդանան՝ Հովհաննեսի մոտ՝ նրանից մկրտվելու։","14":"Հովհաննեսը կանխեց նրան՝ ասելով. «Ե՛ս պետք է քեզանից մկրտվեմ, և դո՞ւ ես ինձ մոտ գալիս»։","15":"Հիսուսը պատասխանեց ու ասաց նրան. «Հիմա թո՛ւյլ տուր, որովհետև մեզ հարկ է այսպես կատարել ամբողջ արդարությունը»։ Այդ ժամանակ Հովհաննեսը նրան թույլ տվեց։","16":"Եվ Հիսուսը մկրտվելուց հետո իսկույն դուրս ելավ ջրից։ Եվ ահա երկինքը բացվեց նրան, և տեսավ Աստծու Հոգին, որ աղավնակերպ իջնում էր ու գալիս էր իր վրա։","17":"Եվ ահա երկնքից ձայն լսվեց, որ ասում էր. «Դա է իմ սիրելի որդին, որ ունի իմ բարեհաճությունը»։"},"4":{"1":"Այդ ժամանակ Հիսուսը Հոգու կողմից անապատ տարվեց՝ սատանայից փորձվելու։","2":"Նա քառասուն օր ու քառասուն գիշեր ծոմ պահելուց հետո քաղց զգաց։","3":"Եվ փորձիչը, նրան մոտենալով, ասաց. «Եթե Աստծու Որդին ես, ասա՛, որ այս քարերը հաց դառնան»։","4":"Նա պատասխանեց ու ասաց. «Գրված է. \"Ոչ միայն հացով է մարդն ապրում, այլև այն ամեն խոսքով, որ Աստծու բերանից է ելնում\" (Բ Օր. 8.3)»։","5":"Այդ ժամանակ սատանան նրան տարավ սուրբ քաղաքը, տաճարի աշտարակի վրա կանգնեցրեց","6":"ու նրան ասաց. «Եթե Աստծու Որդին ես, քեզ ցա՛ծ նետիր, որովհետև գրված է. \"Իր հրեշտակներին քեզ համար պիտի պատվիրի, և նրանք քեզ ձեռքերի վրա պիտի բարձրացնեն, որ երբեք ոտքդ քարին չխփես\" (Սաղ. 91.11ա, 12)»։","7":"Հիսուսը նրան ասաց. «Դարձյալ գրված է. \"Տիրոջը՝ քո Աստծուն, չփորձես\" (Բ Օր. 6.16)»։","8":"Սատանան Հիսուսին դարձյալ տարավ մի շատ բարձր լեռ և նրան ցույց տվեց աշխարհի բոլոր թագավորություններն ու նրանց փառքը։","9":"Եվ նրան ասաց. «Այս ամենը քեզ կտամ, եթե առջևս ընկնելով երկրպագես ինձ»։","10":"Այդ ժամանակ Հիսուսը նրան ասաց. «Հեռո՛ւ գնա, սատանա՛, որովհետև գրված է. \"Տիրոջը՝ քո Աստծուն, կերկրպագես ու միայն նրան կպաշտես\" (Բ Օր. 6.13)»։","11":"Այդ ժամանակ սատանան նրան թողեց, և ահա հրեշտակներ մոտ եկան ու ծառայում էին նրան։","12":"Երբ Հիսուսը լսեց, որ Հովհաննեսը մատնվել է, գնաց Գալիլեա.","13":"թողնելով Նազարեթը՝ եկավ բնակվեց լճի եզերքին գտնվող Կափառնաումում՝ Զաբուղոնի և Նեփթաղիմի սահմաններում,","14":"որպեսզի կատարվեր Եսայի մարգարեի միջոցով ասված խոսքը.","15":"«Զաբուղոնի՛ երկիր ու Նեփթաղիմի՛ երկիր, ծովի ճանապարհ՝ Հորդանանից այն կողմ, հեթանոսների Գալիլեա՛.","16":"ժողովուրդը, որ խավարի մեջ էր նստած, մեծ լույս տեսավ, և մահվան ստվերով աշխարհում նստողների համար լույս ծագեց» (Ես. 9.1-2)։","17":"Այդ ժամանակից Հիսուսն սկսեց քարոզել ու ասել. «Ապաշխարե՛ք, որովհետև մոտեցել է երկնքի արքայությունը»։","18":"Մինչ Հիսուսը շրջում էր Գալիլեայի լճի եզերքով, տեսավ երկու եղբայրների՝ Սիմոնին, որ Պետրոս կոչվեց, և Անդրեասին՝ նրա եղբորը. նրանք ուռկան էին գցում լճի մեջ, որովհետև ձկնորսներ էին։","19":"Հիսուսը նրանց ասաց. «Եկե՛ք իմ հետևից, և ես ձեզ մարդկա՛նց որսորդներ կդարձնեմ»։","20":"Նրանք, իսկույն իրենց ուռկանները թողնելով, գնացին նրա հետևից։","21":"Այնտեղից առաջանալով՝ Հիսուսը տեսավ երկու ուրիշ եղբայրների՝ Զեբեդեոսի որդի Հակոբոսին ու նրա եղբորը՝ Հովհաննեսին, իրենց հոր՝ Զեբեդեոսի հետ նավի մեջ ուռկանները կարգի բերելիս։ Հիսուսը կանչեց նրանց։","22":"Նրանք, իսկույն թողնելով նավն ու իրենց հորը, գնացին նրա հետևից։","23":"Հիսուսը շրջում էր ամբողջ Գալիլեայում, ուսուցանում նրանց ժողովարաններում, արքայության Ավետարանը քարոզում և ժողովրդի մեջ եղած բոլոր հիվանդություններն ու ցավերը բժշկում։","24":"Նրա համբավը տարածվեց ամբողջ Ասորիքով մեկ. Հիսուսի մոտ բերեցին բոլոր հիվանդներին, որոնք տառապում էին զանազան ցավերից ու տանջանքներից՝ դիվահարների, լուսնոտների, անդամալույծների, և նա բժշկում էր նրանց։","25":"Նրա հետևից ժողովրդի մեծ բազմություն էր գնում, որ եկել էր Գալիլեայից, Դեկապոլիսից, Երուսաղեմից, Հրեաստանից ու Հորդանանի մյուս կողմից։"},"5":{"1":"Հիսուսը, ժողովրդի բազմությունը տեսնելով, բարձրացավ լեռը։ Երբ նա նստեց, աշակերտները նրան մոտեցան։","2":"Եվ նա, բերանը բացելով, ուսուցանում էր նրանց ու ասում.","3":"«Երանի՜ հոգով աղքատներին, որովհետև նրանցն է երկնքի արքայությունը։","4":"Երանի՜ սգավորներին, որովհետև նրանք կմխիթարվեն։","5":"Երանի՜ հեզերին, որովհետև նրանք կժառանգեն երկիրը։","6":"Երանի՜ նրանց, ովքեր քաղցած են և ծարավ արդարության, որովհետև նրանք կկշտանան։","7":"Երանի՜ ողորմածներին, որովհետև նրանք ողորմություն կգտնեն։","8":"Երանի՜ սրտով մաքուրներին, որովհետև նրանք Աստծուն կտեսնեն։","9":"Երանի՜ խաղաղարարներին, որովհետև նրանք Աստծու որդիներ կկոչվեն։","10":"Երանի՜ արդարության համար հալածվողներին, որովհետև երկնքի արքայությունը նրանցն է։","11":"Երանի՜ ձեզ, երբ ձեզ նախատեն ու հալածեն և իմ պատճառով ձեր մասին ամեն տեսակ չար բան զրպարտությամբ ասեն։","12":"Ուրախացե՛ք ու ցնծացե՛ք, որովհետև երկնքում ձեր վարձը շատ է, որովհետև այդպես հալածեցին մարգարեներին, որոնք ձեզանից առաջ էին։","13":"Դուք եք երկրի աղը. եթե աղն իր համը կորցնի, ինչո՞վ կհամեմվի. այլևս ոչնչի պիտանի չի լինի, այլ դուրս կթափվի ու մարդկանց կողմից ոտնակոխ կլինի։","14":"Դուք եք աշխարհի լույսը։ Մի քաղաք, որ լեռան վրա է կառուցված, չի կարող թաքնվել։","15":"Ոչ էլ ճրագը վառում ու գրվանի տակ են դնում, այլ դնում են աշտանակի վրա, և այն լույս է տալիս բոլոր նրանց, ովքեր տան մեջ են։","16":"Այդպես էլ թող ձեր լույսը մարդկանց առաջ փայլի, որպեսզի տեսնեն ձեր բարի գործերն ու փառավորեն ձեր Հորը, որ երկնքում է։","17":"Մի՛ կարծեք, թե ես եկա օրենքը կամ մարգարեներին ջնջելու. ես չեկա ջնջելու, այլ իրականացնելու։","18":"Ճշմարիտ եմ ասում ձեզ. մինչև երկինքն ու երկիրը անցնեն, օրենքից մի կետ կամ մի փոքր նշանագիր անգամ չի անցնի, մինչև որ ամեն ինչ չիրականանա։","19":"Արդ, ով այս պատվիրաններից ամենափոքրերից մեկն անգամ անտեսի և մարդկանց այդպես ուսուցանի, նա երկնքի արքայության մեջ ամենափոքրը կկոչվի։ Բայց ով կատարի և ուսուցանի, երկնքի արքայության մեջ նա մեծ կկոչվի։","20":"Ասում եմ ձեզ. եթե ձեր արդարությունը չլինի ավելին, քան դպիրներինն ու փարիսեցիներինը, երկնքի արքայություն չեք մտնի։","21":"Լսել եք, թե ի՛նչ ասվեց նախնիներին. \"Մի՛ սպանիր\" (Ելք 20.13, Բ Օր. 5.17). իսկ ով սպանի, դատաստանի կենթարկվի։","22":"Բայց ես ասում եմ ձեզ. ամեն ոք, ով զուր տեղն իր եղբոր վրա բարկանա, դատաստանի կենթարկվի, և ով իր եղբորը \"հիմար\" ասի, ատյանի ենթակա կլինի, և ով իր եղբորը \"անմիտ\" ասի, գեհենի կրակին կդատապարտվի։","23":"Արդ, եթե սեղանի վրա քո ընծան մատուցելիս լինես ու այնտեղ հիշես, որ եղբայրդ քո դեմ որևէ բան ունի,","24":"թո՛ղ քո ընծան այնտեղ՝ սեղանի առաջ, և գնա՛, նախ եղբորդ հետ հաշտվի՛ր, ապա արի՛, քո ընծան մատուցի՛ր։","25":"Փութով հաշտվի՛ր քո հակառակորդի հետ, քանի դեռ նրա հետ ճանապարհին ես. գուցե նա քեզ դատավորին հանձնի, իսկ դատավորը՝ դահճին, և դու բանտ նետվես։","26":"Ճշմարիտ եմ ասում քեզ. այնտեղից դուրս չես գա, մինչև վերջին լուման չվճարես։","27":"Լսել եք, թե ի՛նչ ասվեց. \"Մի՛ շնանա\" (Ելք 20.14, Բ Օր. 5.18)։","28":"Բայց ես ասում եմ ձեզ. ով ցանկասիրությամբ նայի որևէ կնոջ, արդեն իր սրտում նրա հետ շնացած կլինի։","29":"Եթե քո աջ աչքը քեզ գայթակղեցնում է, հանի՛ր այն ու քեզանից դե՛ն գցիր, որովհետև քեզ համար լավ է, որ անդամներիցդ մեկը կորչի, քան ամբողջ մարմինդ գեհեն ընկնի։","30":"Եթե քո աջ ձեռքը գայթակղեցնում է քեզ, կտրի՛ր այն ու քեզանից դե՛ն գցիր, որովհետև քեզ համար լավ է, որ անդամներիցդ մեկը կորչի, քան ամբողջ մարմինդ գեհեն ընկնի։","31":"Ասվել է նաև. \"Ով իր կնոջն արձակում է, թող նրան արձակման թուղթ տա\" (Բ Օր. 24.1-4, Մտթ. 19.7)։","32":"Բայց ես ասում եմ ձեզ. ով իր կնոջն առանց պոռնկության պատճառի արձակում է, ինքն է նրան շնության մղում, իսկ ով արձակված կնոջ հետ է ամուսնանում, շնություն է անում։","33":"Դարձյալ լսել եք, թե ի՛նչ ասվեց նախնիներին. \"Սուտ մի՛ երդվիր, բայց կատարի՛ր այն, ինչ երդվել ես Տիրոջը\" (Ղևտ. 19.12)։","34":"Սակայն ես ասում եմ ձեզ. բնավ մի՛ երդվիր ո՛չ երկնքով, քանի որ այն Աստծու գահն է,","35":"ո՛չ երկրով, քանի որ նրա ոտքերի պատվանդանն է, ո՛չ Երուսաղեմով, որ մեծ Թագավորի քաղաքն է։","36":"Ո՛չ էլ քո գլխով երդվիր, որովհետև մի մազ անգամ չես կարող սպիտակ կամ սև դարձնել։","37":"Ձեր խոսքը թող լինի \"այո\"-ն \"այո\", և \"ոչ\"-ը՝ \"ոչ\". սրանից ավելին չարից է։","38":"Լսել եք, թե ի՛նչ ասվեց. \"Աչքի դիմաց՝ աչք և ատամի դիմաց՝ ատամ\" (Ելք 21.24, Ղևտ. 24.20, Բ Օր. 19.21)։","39":"Բայց ես ասում եմ ձեզ. չարին հակառակ մի՛ կանգնիր, այլ ով քո ծնոտի աջ կողմին ապտակի, մյուս կո՛ղմն էլ նրան դարձրու։","40":"Եթե մեկը ցանկանա քեզ դատի տալ և շապիկդ առնել, բաճկո՛նդ էլ տուր նրան։","41":"Եթե մեկը քեզ ստիպի իր հետ մեկ մղոն գնալ, նրա հետ երկո՛ւ մղոն էլ գնա։","42":"Ով քեզանից խնդրում է, տո՛ւր, ով քեզանից ուզում է փոխ առնել, երես մի՛ դարձրու։","43":"Լսել եք, թե ի՛նչ ասվեց. \"Պիտի սիրես ընկերոջդ (Ղևտ. 19.18, Մտթ. 22.39) և պիտի ատես թշնամուդ\"։","44":"Բայց ես ասում եմ ձեզ. սիրե՛ք ձեր թշնամիներին, օրհնե՛ք ձեզ անիծողներին, բարի՛ք արեք ձեզ ատողներին և աղոթե՛ք ձեզ չարչարողների ու հալածողների համար,","45":"որպեսզի որդիները լինեք ձեր Հոր, որ երկնքում է. որովհետև նա իր արեգակը ծագեցնում է և՛ չարերի, և՛ բարիների վրա ու անձրև է բերում և՛ արդարների, և՛ անարդարների վրա։","46":"Որովհետև եթե ձեզ սիրողների՛ն սիրեք, ի՞նչ վարձ ունեք. չէ՞ որ մաքսավորներն էլ նույնն են անում։","47":"Եվ եթե ողջունեք միայն ձեր եղբայրներին, ի՞նչ ավել բան արած կլինեք. չէ՞ որ հեթանոսներն էլ են նույնն անում։","48":"Արդ, դուք կատարյա՛լ եղեք, ինչպես որ ձեր երկնավոր Հայրն է կատարյալ»։"},"6":{"1":"«Զգո՛ւյշ եղեք, որ ձեր ողորմությունը չանեք մարդկանց առաջ՝ նրանց ցույց տալու համար, այլապես վարձ չեք ունենա ձեր Հորից, որ երկնքում է։","2":"Արդ, երբ ողորմություն անես, մի՛ փողահարիր քո առաջ, ինչպես կեղծավորներն են ժողովարաններում և փողոցներում անում, որպեսզի մարդկանցից փառավորվեն։ Ճշմարիտ եմ ասում ձեզ. նրանք իրենց վարձն ստացել են։","3":"Բայց երբ դու ողորմություն անես, թող քո ձախ ձեռքը չիմանա, թե քո աջն ի՛նչ է անում,","4":"որպեսզի քո ողորմությունը ծածուկ լինի, և քո Հայրը, որ տեսնում է ծածուկը, քեզ հայտնապես կհատուցի։","5":"Երբ աղոթք անես, չլինես կեղծավորների պես, որոնք սիրում են ժողովարաններում և հրապարակների անկյուններում կանգնած աղոթել, որպեսզի մարդկանց տեսանելի լինեն։ Ճշմարիտ եմ ասում ձեզ, որ նրանք իրենց վարձն ստացել են։","6":"Այլ երբ դու աղոթես, մտի՛ր քո սենյակը, փակի՛ր դուռդ և ծածուկ աղոթի՛ր քո Հորը, և քո Հայրը, որ տեսնում է ծածուկը, հայտնապես կհատուցի քեզ։","7":"Երբ աղոթք եք անում, մի՛ շատախոսեք հեթանոսների պես, որոնք կարծում են, թե իրենց շատախոսությամբ լսելի պիտի լինեն։","8":"Արդ, նրանց մի՛ նմանվեք, որովհետև ձեր Հայրը գիտի, թե ի՛նչ է ձեզ պետք նախքան նրանից ձեր որևէ բան խնդրելը։","9":"Արդ, դուք այսպե՛ս աղոթեք. Տերունական աղոթք \"Հա՛յր մեր, որ երկնքում ես, սուրբ լինի քո անունը.","10":"քո արքայությունը գա, քո կամքը լինի ինչպես երկնքում, այնպես էլ երկրի վրա։","11":"Տո՛ւր մեզ այսօր մեր հանապազօրյա հացը։","12":"Եվ ների՛ր մեզ մեր պարտքերը, ինչպես մենք ենք ներում մեր պարտապաններին։","13":"Եվ մի՛ տար մեզ փորձության, այլ ազատի՛ր մեզ չարից\"։","14":"Որովհետև եթե դուք մարդկանց ներեք իրենց հանցանքները, ձեր երկնավոր Հայրն էլ ձեզ կների։","15":"Իսկ եթե դուք մարդկանց չներեք իրենց հանցանքները, ձեր Հայրն էլ ձեզ չի ների ձեր հանցանքները։","16":"Եվ երբ ծոմ եք պահում, տրտմերես մի՛ եղեք կեղծավորների պես, որոնք իրենց երեսը խոժոռում են, որպեսզի մարդկանց ցույց տան, թե ծոմ են պահում։ Ճշմարիտ եմ ասում ձեզ, որ նրանք իրենց վարձն ստացել են։","17":"Այլ երբ դու ծոմ պահես, օծի՛ր գլուխդ և լվա՛ երեսդ,","18":"որպեսզի ցույց չտաս մարդկանց, թե ծոմ ես պահում, այլ ծածուկ կերպով երևաս քո Հորը, և քո Հայրը, որ տեսնում է ծածուկը, քեզ հայտնապես կհատուցի։","19":"Ձեզ համար գանձեր մի՛ դիզեք երկրի վրա, որտեղ ցեցն ու ժանգն ապականում են, և որտեղ գողերը սողոսկում են ու գողանում։","20":"Այլ ձեզ համար երկնքո՛ւմ գանձեր դիզեք, որտեղ ո՛չ ցեցը, ո՛չ ժանգը չեն ապականում, ո՛չ էլ գողերն են սողոսկում ու գողանում.","21":"որովհետև որտեղ ձեր գանձն է, այնտեղ էլ ձեր սիրտը կլինի։","22":"Մարմնի ճրագն աչքն է. արդ, եթե քո աչքը պարզ լինի, ամբողջ մարմինդ էլ լուսավոր կլինի։","23":"Բայց եթե քո աչքը չար է, քո ամբողջ մարմինը խավար կլինի։ Արդ, եթե քո մեջ եղած լույսը խավար է, ապա խավարը որքա՜ն առավել կլինի։","24":"Ոչ ոք չի կարող երկու տիրոջ ծառայել, որովհետև կա՛մ մեկին կատի և մյուսին կսիրի, կա՛մ մեկին կմեծարի և մյուսին կարհամարհի։ Չեք կարող ծառայել և՛ Աստծուն, և՛ մամոնային։","25":"Դրա համար էլ ասում եմ ձեզ. մի՛ հոգացեք ձեր կյանքի համար, թե ի՛նչ պիտի ուտեք կամ ի՛նչ պիտի խմեք, ոչ էլ ձեր մարմնի համար, թե ի՛նչ պիտի հագնեք։ Չէ՞ որ կյանքն առավել է, քան կերակուրը, և մարմինն առավել է, քան հագուստը։","26":"Նայե՛ք երկնքի թռչուններին, որոնք ո՛չ սերմանում են, ո՛չ հնձում և ո՛չ էլ շտեմարանների մեջ ամբարում, և ձեր երկնավոր Հայրը նրանց կերակրում է։ Չէ՞ որ դուք առավել եք, քան նրանք։","27":"Ձեզանից ո՞վ կարող է հոգալով իր հասակի վրա ևս մի կանգուն ավելացնել։","28":"Եվ հագուստի համար ինչո՞ւ եք հոգում. նայե՛ք վայրի շուշաններին՝ ինչպե՛ս են աճում. ո՛չ ջանք են թափում, ո՛չ էլ մանում։","29":"Ասում եմ ձեզ, որ նույնիսկ Սողոմոնը իր ամբողջ փառքի մեջ նրանցից ոչ մեկի պես չհագնվեց։","30":"Իսկ եթե դաշտի խոտին, որ այսօր կա, բայց վաղը հնոցն է գցվում, Աստված այդպես է հագցնում, որքա՜ն առավել ձե՛զ կհագցնի, թերահավատնե՛ր։","31":"Ուրեմն մի՛ մտահոգվեք ասելով՝ ի՛նչ ենք ուտելու կամ ի՛նչ ենք խմելու կամ ի՛նչ ենք հագնելու,","32":"որովհետև այդ ամենը հեթանոսներն են փնտրում. որովհետև ձեր երկնավոր Հայրը գիտի, որ դուք այդ ամենի կարիքն ունեք։","33":"Դուք նախ Աստծու արքայությունն ու նրա արդարությո՛ւնը փնտրեք, և այդ ամենը ավելիով ձեզ կտրվի։","34":"Արդ, վաղվա մասին մի՛ հոգացեք, որովհետև վաղվա օրն ունի իր հոգսերը. յուրաքանչյուր օրվա հոգսերն ինքնին բավական են»։"},"7":{"1":"«Մի՛ դատեք, որ չդատվեք.","2":"որովհետև ինչ դատաստանով որ դատեք, նրանով պիտի դատվեք, և ինչ չափով որ չափեք, նրանով էլ ձեզ կչափվի։","3":"Եվ ինչո՞ւ եղբորդ աչքի միջի շյուղը տեսնում ես, իսկ քո աչքի միջի գերանը չես նկատում։","4":"Կամ ինչպե՞ս ես եղբորդ ասում՝ \"Թող շյուղն աչքիդ միջից հանեմ\", երբ ահա քո աչքի մեջ գերան կա։","5":"Կեղծավո՛ր, նախ քո աչքից գերա՛նը հանիր և այդ ժամանակ կտեսնես, թե ինչպե՛ս եղբորդ աչքից շյուղը հանես։","6":"Սուրբ բանը շներին մի՛ տվեք, ոչ էլ ձեր մարգարիտները խոզերի առաջ գցեք, որպեսզի դրանք ոտնակոխ չանեն ու շրջվելով ձեզ պատառոտեն։","7":"Խնդրե՛ք, և կտրվի ձեզ, փնտրե՛ք և կգտնեք, բախե՛ք, և ձեզ կբացվի.","8":"որովհետև ով խնդրում է, ստանում է, ով փնտրում է, գտնում է, ով բախում է, նրան բացվում է։","9":"Կամ ո՞վ է ձեզանից այն մարդը, որից եթե իր որդին հաց խնդրի, նրան քար կտա,","10":"կամ ձուկ խնդրի, նրան օձ կտա։","11":"Արդ, եթե դուք, որ չար եք, ձեր զավակներին բարի պարգևներ տալը գիտեք, հապա որքա՜ն առավել ձեր Հայրը, որ երկնքում է, բարիքներ կտա նրանց, ովքեր խնդրում են իրեն։","12":"Այն ամենը, ինչ կամենում եք, որ մարդիկ ձեզ անեն, այդպես և դո՛ւք արեք նրանց, որովհետև սա են օրենքը և մարգարեները։","13":"Նեղ դռնո՛վ ներս մտեք, որովհետև լայն է այն դուռը, և ընդարձակ՝ այն ճանապարհը, որ դեպի կործանում է տանում, և դրանով մտնողները շատ են։","14":"Որքա՜ն նեղ է այն դուռը, և դժվարանցանելի՝ ճանապարհը, որ դեպի կյանք է տանում. քիչ են այն գտնողները։","15":"Զգո՛ւյշ եղեք սուտ մարգարեներից, որ ձեզ մոտ են գալիս ոչխարի հանդերձով, բայց ներքուստ հափշտակող գայլեր են։","16":"Իրենց պտուղների՛ց նրանց կճանաչեք. մի՞թե փշերից խաղող են քաղում կամ տատասկից՝ թուզ։","17":"Այդպես էլ ամեն լավ ծառ լավ պտուղ է տալիս, իսկ վատ ծառը՝ վատ պտուղ։","18":"Լավ ծառը չի կարող վատ պտուղ տալ, ոչ էլ վատ ծառը՝ լավ պտուղ։","19":"Ամեն ծառ, որ լավ պտուղ չի տալիս, կտրվում է ու կրակի մեջ գցվում։","20":"Ուրեմն իրենց պտուղների՛ց նրանց կճանաչեք։","21":"Ոչ թե ամեն ինձ \"Տե՛ր, Տե՛ր\" ասողն է երկնքի արքայություն մտնելու, այլ նա, ով կատարում է իմ Հոր կամքը, որ երկնքում է։","22":"Այն օրը շատերն ինձ կասեն. \"Տե՛ր, Տե՛ր, չէ՞ որ քո անունով մարգարեացանք, քո անունով դևեր հանեցինք և քո անունով շատ հրաշքներ գործեցինք\"։","23":"Ես էլ այն ժամանակ նրանց կհայտնեմ. \"Ես ձեզ երբեք չեմ ճանաչել. ինձանից հեռացե՛ք, ո՛վ անօրենություն գործողներ\"։","24":"Արդ, ամեն ոք, ով լսում է իմ այս խոսքերն ու դրանք կատարում, կնմանեցնեմ մի իմաստուն մարդու, որն իր տունը կառուցեց ժայռի վրա։","25":"Անձրևը եկավ, գետերը հորդեցին, քամիները փչեցին և զարկեցին տանը, բայց այն չկործանվեց, որովհետև ժայռի վրա էր հաստատված։","26":"Իսկ ամեն ոք, ով լսում է իմ այս խոսքերն ու դրանք չի կատարում, կնմանվի մի անխելք մարդու, որն իր տունը կառուցեց ավազի վրա։","27":"Անձրևը եկավ, գետերը հորդեցին, քամիները փչեցին, զարկեցին տանը, ու այն կործանվեց, և նրա կործանումը մեծ եղավ»։","28":"Երբ Հիսուսն այս խոսքերն ավարտեց, ժողովուրդը զարմացած էր նրա ուսուցման վրա,","29":"որովհետև նրանց ուսուցանում էր իշխանություն ունեցողի պես և ոչ թե դպիրների նման։"},"8":{"1":"Երբ Հիսուսն իջավ լեռան վրայից, նրա հետևից ժողովրդի մեծ բազմություն գնաց։","2":"Ահա մոտեցավ մի բորոտ, երկրպագեց նրան և ասաց. «Տե՛ր, եթե կամենաս, կարող ես ինձ մաքրել»։","3":"Հիսուսը, ձեռքը մեկնելով, դիպավ նրան ու ասաց. «Կամենում եմ, մաքրվի՛ր»։ Եվ բորոտությունը նրանից իսկույն մաքրվեց։","4":"Հիսուսը նրան ասաց. «Զգո՛ւյշ եղիր, ոչ ոքի չասես, այլ գնա՛, քեզ քահանայի՛ն ցույց տուր և իբրև վկայություն՝ ընծա՛ մատուցիր նրանց, ինչպես որ Մովսեսն է պատվիրել»։","5":"Երբ Հիսուսը Կափառնաում մտավ, նրան մոտեցավ մի հարյուրապետ, որ աղաչում էր նրան","6":"և ասում. «Տե՛ր, ծառաս անդամալույծ պառկած է տանը և սարսափելի տառապում է»։","7":"Հիսուսը նրան ասաց. «Ես կգամ, կբժշկեմ նրան»։","8":"Հարյուրապետը պատասխանեց և ասաց. «Տե՛ր, ես արժանի չեմ, որ իմ հարկի տակ մտնես. միայն խոսքո՛վ ասա, և ծառաս կբժշկվի։","9":"Որովհետև ես էլ իշխանության տակ գտնվող մարդ եմ, ձեռքիս տակ զինվորներ ունեմ. սրան ասում եմ՝ գնա՛, ու գնում է, մյուսին՝ ե՛կ, ու գալիս է, ծառայիս էլ թե՝ այս բա՛նն արա, և անում է»։","10":"Երբ Հիսուսը լսեց, զարմացավ և իրեն հետևողներին ասաց. «Ճշմարիտ եմ ասում ձեզ. նույնիսկ Իսրայելում այսպիսի հավատ չգտա։","11":"Ասում եմ ձեզ, որ արևելքից ու արևմուտքից շատերը կգան և Աբրահամի, Իսահակի ու Հակոբի հետ երկնքի արքայության մեջ կնստեն,","12":"իսկ արքայության որդիները կգցվեն դուրս՝ արտաքին խավարը. այնտեղ կլինի լաց ու ատամների կրճտոց»։","13":"Եվ Հիսուսը հարյուրապետին ասաց. «Գնա՛ և ինչպես որ հավատացիր, այդպես էլ թող լինի քեզ»։ Եվ այդ պահին նրա ծառան բժշկվեց։","14":"Երբ Հիսուսը Պետրոսի տուն եկավ, տեսավ նրա զոքանչին՝ ջերմության մեջ պառկած։","15":"Հիսուսը բռնեց նրա ձեռքից, ու ջերմությունը նրան թողեց։ Նա վեր կացավ ու ծառայում էր նրանց։","16":"Երբ երեկո եղավ, Հիսուսի մոտ շատ դիվահարների բերեցին, և նա խոսքով հանեց ոգիներին ու բոլոր հիվանդներին բժշկեց,","17":"որպեսզի իրականանար Եսայի մարգարեի միջոցով ասվածը. «Նա մեր հիվանդությունները վերցրեց ու մեր ցավերը կրեց» (Ես. 53.4ա)։","18":"Երբ Հիսուսը տեսավ իրեն շրջապատող ժողովրդի մեծ բազմությունը, աշակերտներին կարգադրեց լճի մյուս կողմն անցնել։","19":"Նրան մոտեցավ մի դպիր և ասաց. «Վարդապե՛տ, ես քո հետևից կգամ, ո՛ւր էլ գնաս»։","20":"Հիսուսը նրան ասաց. «Աղվեսները որջեր ունեն, երկնքի թռչունները՝ բներ, բայց Մարդու Որդին իր գլուխը դնելու տեղ չունի»։","21":"Նրա աշակերտներից մեկն ասաց նրան. «Տե՛ր, թո՛ւյլ տուր ինձ՝ գնամ նախ հորս թաղեմ»։","22":"Հիսուսը նրան ասաց. «Արի՛ իմ հետևից և թո՛ղ մեռածներին, որ իրենք թաղեն իրենց մեռելներին»։","23":"Երբ Հիսուսը նավ մտավ, աշակերտները գնացին նրա հետևից։","24":"Հանկարծ լճի վրա այնպիսի մեծ ալեկոծություն եղավ, որ նավը ծածկվում էր ալիքներով։ Իսկ նա քնած էր։","25":"Աշակերտները մոտենալով արթնացրին նրան ու ասացին. «Տե՛ր, փրկի՛ր մեզ, կորչում ենք»։","26":"Եվ նրանց ասաց. «Ինչո՞ւ եք վախենում, թերահավատնե՛ր»։ Այդ ժամանակ վեր կացավ, սաստեց հողմերին ու լճին, և կատարյալ խաղաղություն եղավ։","27":"Իսկ մարդիկ զարմացան և ասում էին. «Ի՞նչ տեսակ մարդ է սա, որ հողմերն ու լիճն էլ են հնազանդվում նրան»։","28":"Երբ անցավ լճի մյուս կողմը՝ գադարացիների երկիրը, նրան պատահեցին երկու դիվահարներ, որոնք գալիս էին գերեզմաններից։ Նրանք այնքան ահազդու էին, որ որևէ մեկը չէր կարողանում այդ ճանապարհով անցնել։","29":"Եվ ահա նրանք աղաղակեցին ու ասացին. «Ի՞նչ կա մեր և քո միջև, Աստծո՛ւ Որդի։ Այստեղ ես եկել, որ ժամանակից շուտ մեզ տանջե՞ս»։","30":"Եվ նրանցից հեռու խոզերի մի երամակ էր արածում։","31":"Դևերը նրան աղաչում էին ու ասում. «Եթե մեզ հանես, այն խոզերի երամակի մե՛ջ ուղարկիր»։","32":"Եվ նրանց ասաց. «Գնացե՛ք», և դևերը դուրս ելան ու խոզերի մեջ գնացին։ Եվ ամբողջ երամակը դարավանդից դեպի լիճը վազեց, և ջրի մեջ խեղդվեցին։","33":"Իսկ խոզարածները փախան և քաղաք գնալով՝ պատմեցին ամեն ինչ, նաև դիվահարների հետ պատահածը։","34":"Եվ ահա ողջ քաղաքը Հիսուսին ընդառաջ դուրս ելավ։ Երբ նրան տեսան, աղաչեցին, որ հեռանա իրենց սահմաններից։"},"9":{"1":"Հիսուսը, նավ նստելով, լճի մյուս կողմն անցավ ու իր քաղաքը եկավ։","2":"Ահա նրա մոտ բերեցին մի անդամալույծի, որ պառկած էր մահճի մեջ։ Հիսուսը, նրանց հավատը տեսնելով, անդամալույծին ասաց. «Քաջալերվի՛ր, որդյա՛կ, քո մեղքերը քեզ ներված են»։","3":"Դպիրներից ոմանք իրենց մտքում ասացին. «Սա հայհոյում է»։","4":"Հիսուսը, նրանց միտքը հասկանալով, ասաց. «Ինչո՞ւ եք ձեր սրտում չար բաներ խորհում։","5":"Ի՞նչն է ավելի հեշտ. ասել՝ \"Քո մեղքերը ներված են\", թե՞ ասել՝ \"Վե՛ր կաց ու քայլի՛ր\"։","6":"Բայց որպեսզի իմանաք, որ Մարդու Որդին իշխանություն ունի երկրի վրա մեղքերին թողություն տալու, այդ ժամանակ անդամալույծին ասաց. \"Վե՛ր կաց, մահիճդ ա՛ռ ու քո տո՛ւն գնա\"»։","7":"Նա վեր կացավ և իր տուն գնաց։","8":"Երբ ժողովրդի բազմությունը տեսավ, զարմացավ. փառավորում էին Աստծուն, որ մարդկանց այդպիսի իշխանություն է տվել։","9":"Հիսուսը, այնտեղից առաջ անցնելով, տեսավ Մատթեոս անունով մի մարդու, որ նստած էր մաքսատանը։ Նրան ասաց. «Արի՛ իմ հետևից»։ Նա վեր կացավ, գնաց նրա հետևից։","10":"Երբ Հիսուսը նրա տանը սեղան էր նստել, ահա շատ մաքսավորներ ու մեղավորներ եկան բազմեցին Հիսուսի և նրա աշակերտների հետ։","11":"Փարիսեցիները, տեսնելով նրա աշակերտներին, ասացին. «Ինչո՞ւ է ձեր վարդապետը մաքսավորների ու մեղավորների հետ ուտում»։","12":"Բայց երբ Հիսուսը լսեց, նրանց ասաց. «Առողջները բժշկի կարիք չունեն, այլ հիվանդները։","13":"Գնացեք սովորե՛ք, թե ի՛նչ է նշանակում \"Ողորմություն եմ ուզում և ոչ թե զոհ\" (Ովս. 6.6). որովհետև ես արդարներին կանչելու չեմ եկել, այլ մեղավորներին»։","14":"Այդ ժամանակ Հովհաննեսի աշակերտները մոտեցան Հիսուսին ու ասացին. «Ինչո՞ւ մենք և փարիսեցիները հաճախ ենք ծոմ պահում, իսկ քո աշակերտները ծոմ չեն պահում»։","15":"Եվ Հիսուսը նրանց ասաց. «Մի՞թե փեսայի բարեկամները կարող են սուգ անել, քանի դեռ փեսան նրանց հետ է։ Բայց կգան օրեր, երբ փեսան նրանց միջից կվերցվի, ու այն ժամանակ նրանք ևս ծոմ կպահեն։","16":"Ոչ ոք հին հագուստի վրա նոր կտորից կարկատան չի գցի, որովհետև այն ամբողջությամբ հագուստից կքաշի, և է՛լ ավելի վատ պատռվածք կառաջանա։","17":"Ոչ էլ նոր գինին են հին տիկերի մեջ լցնում, այլապես տիկերը կպատռվեն, գինին կթափվի, տիկերն էլ կփչանան։ Այլ նոր գինին նոր տիկերի մեջ են լցնում, և երկուսն էլ պահպանվում են»։","18":"Նրանց հետ այս բաները խոսելու ժամանակ ահա մի իշխան եկավ, նրան երկրպագեց ու ասաց. «Աղջիկս հենց նոր մահացավ. բայց արի՛, ձեռքդ նրա վրա՛ դիր, և նա կկենդանանա»։","19":"Հիսուսը վեր կացավ, նրա հետևից գնաց, և նրա աշակերտները ևս։","20":"Եվ ահա տասներկու տարի արյունահոսությամբ տառապող մի կին, հետևից մոտենալով, դիպավ Հիսուսի հագուստի քղանցքին,","21":"որովհետև իր մտքում ասում էր. «Եթե միայն նրա հագուստին դիպչեմ, կփրկվեմ»։","22":"Բայց երբ Հիսուսը շրջվեց և նրան տեսավ, ասաց. «Քաջալերվի՛ր, դո՛ւստր, քո հավատը քեզ փրկեց»։ Եվ կինը նույն պահից բժշկվեց։","23":"Երբ Հիսուսն իշխանի տուն եկավ և տեսավ փողհարներին ու տագնապած մարդկանց,","24":"նրանց ասաց. «Մի կո՛ղմ քաշվեք, որովհետև այդ աղջիկը մեռած չէ, այլ ննջում է»։ Եվ ծաղրում էին նրան։","25":"Երբ մարդկանց դուրս հանեցին, Հիսուսը ներս մտավ, բռնեց աղջկա ձեռքից, և նա վեր կացավ։","26":"Եվ սրա համբավը տարածվեց ողջ երկրով մեկ։","27":"Երբ Հիսուսն այնտեղից հեռանում էր, նրա հետևից երկու կույրեր էին գնում։ Նրանք աղաղակում էին ու ասում. «Ողորմի՛ր մեզ, Դավթի՛ որդի»։","28":"Երբ տուն հասավ, կույրերը մոտեցան նրան։ Հիսուսը նրանց ասաց. «Հավատո՞ւմ եք, որ կարող եմ դա անել»։ Նրան ասացին. «Այո՛, Տե՛ր»։","29":"Այդ ժամանակ դիպավ նրանց աչքերին ու ասաց. «Թող ըստ ձեր հավատի լինի ձեզ»։","30":"Եվ նրանց աչքերը բացվեցին։ Հիսուսը նրանց պատվիրեց՝ ասելով. «Զգո՛ւյշ եղեք, ոչ ոք չիմանա»։","31":"Իսկ նրանք դուրս ելան և նրա համբավը տարածեցին այդ ողջ երկրով մեկ։","32":"Երբ նրանք դուրս էին ելնում, ահա Հիսուսի մոտ բերեցին մի համր դիվահարի։","33":"Երբ դևը դուրս հանվեց, համրը խոսեց։ Եվ մարդիկ զարմացան ու ասացին, որ Իսրայելում այդպիսի բան երբեք չի տեսնվել։","34":"Իսկ փարիսեցիներն ասում էին. «Դևերի իշխանի միջոցով է դևերին հանում»։","35":"Հիսուսը շրջում էր բոլոր քաղաքներով ու գյուղերով, ուսուցանում էր նրանց ժողովարաններում, արքայության Ավետարանը քարոզում, ժողովրդի բոլոր ցավերն ու հիվանդությունները բժշկում։","36":"Նա, ժողովրդի բազմությունը տեսնելով, գթաց նրանց, որ հոգնել և ցիրուցան էին եղել, ինչպես հովիվ չունեցող ոչխարները։","37":"Այդ ժամանակ Հիսուսն իր աշակերտներին ասաց. «Հունձքը շատ է, բայց մշակները՝ քիչ։","38":"Արդ աղաչե՛ք հունձքի Տիրոջը, որ իր հունձքի համար մշակներ ուղարկի»։"},"10":{"1":"Հիսուսն իր մոտ կանչեց տասներկու աշակերտներին, նրանց իշխանություն տվեց պիղծ ոգիներ հանելու և բոլոր ցավերն ու հիվանդությունները բուժելու։","2":"Տասներկու առաքյալների անունները սրանք են. առաջին՝ Սիմոն, որ Պետրոս անվանվեց, նրա եղբայր Անդրեասը,","3":"Զեբեդեոսի որդի Հակոբոս և նրա եղբայրը՝ Հովհաննես, Փիլիպպոս ու Բարթողոմեոս, Թովմաս ու Մատթեոս մաքսավոր, Ալփեոսի որդի Հակոբոս և Ղեբեոս,","4":"Սիմոն Կանանացի ու Հուդա Իսկարիովտացի, որը և մատնեց նրան։","5":"Հիսուսն այս տասներկուսին ուղարկեց և նրանց պատվիրեց՝ ասելով. «Դեպի հեթանոսները տանող ճանապարհով չգնաք և սամարացիների քաղաք չմտնեք.","6":"ավելի լավ է՝ Իսրայելի տան կորած ոչխարների մոտ գնաք։","7":"Երբ գնաք, քարոզե՛ք ու ասե՛ք, որ երկնքի արքայությունը մոտեցել է։","8":"Հիվանդներին բժշկե՛ք, մեռելներին հարությո՛ւն տվեք, բորոտներին մաքրե՛ք, դևերին հանե՛ք. ձրի ստացել եք, ձրի էլ տվե՛ք։","9":"Ձեր գոտիների մեջ ո՛չ ոսկի, ո՛չ արծաթ և ո՛չ էլ պղնձադրամ վերցրեք.","10":"ո՛չ պարկ՝ ճանապարհի համար, ո՛չ երկուական հագուստ, ո՛չ կոշիկներ և ո՛չ էլ գավազան, քանի որ մշակն արժանի է իրեն տրվելիք կերակուրին։","11":"Ո՛ր քաղաքը կամ գյուղը մտնեք, հարցրե՛ք, թե այնտեղ ո՛վ կա ձեզ ընդունելու արժանի, և այնտե՛ղ մնացեք մինչև ձեր ելնելը։","12":"Երբ այդ տունը մտնեք, նրան ողջո՛ւյն տվեք։","13":"Եթե տունն արժանի լինի, ձեր խաղաղությունը նրա վրա կիջնի, իսկ եթե արժանի չլինի, ձեր խաղաղությունը ձեզ կվերադառնա։","14":"Իսկ ով ձեզ չընդունի, ոչ էլ ձեր խոսքին ականջ դնի, երբ այդ տնից կամ այդ քաղաքից դուրս ելնեք, ձեր ոտքերից փոշին թա՛փ տվեք։","15":"Ճշմարիտ եմ ասում ձեզ, որ դատաստանի օրը սոդոմացիների և գոմորացիների երկրի համար ավելի հեշտ կլինի, քան այդ քաղաքի։","16":"Ահա ես ձեզ ուղարկում եմ որպես ոչխարներ՝ գայլերի մեջ։ Արդ խորագե՛տ եղեք, ինչպես օձերը, և միամիտ, ինչպես աղավնիները։","17":"Զգո՛ւյշ եղեք մարդկանցից, որովհետև ձեզ դատարաններ կհանձնեն ու իրենց ժողովարաններում ձեզ կտանջեն։","18":"Իմ պատճառով կառավարիչների ու թագավորների առաջ կտարվեք՝ նրանց ու հեթանոսներին վկայություն տալու համար։","19":"Բայց երբ ձեզ մատնեն, հոգ մի՛ արեք, թե ինչպե՛ս կամ ի՛նչ եք խոսելու, որովհետև նույն պահին կտրվի ձեզ այն, ինչ խոսելու եք,","20":"քանի որ խոսողը դուք չեք, այլ ձեր Հոր Հոգին, որ խոսում է ձեր մեջ։","21":"Եղբայրը եղբորը մահվան կմատնի, հայրը՝ որդուն, զավակները ծնողների դեմ կելնեն և կսպանեն նրանց։","22":"Եվ իմ անվան պատճառով բոլորի կողմից ատված կլինեք։ Սակայն ով մինչև վերջ համբերի, նա կփրկվի։","23":"Երբ ձեզ այս քաղաքում հալածեն, դեպի մեկ ուրի՛շը փախեք, որովհետև, ճշմարիտ եմ ասում ձեզ, դուք Իսրայելի քաղաքները սպառած չեք լինի մինչև Մարդու Որդու գալուստը։","24":"Աշակերտն ուսուցչից առավել չէ, ոչ էլ ծառան՝ իր տիրոջից։","25":"Աշակերտին բավական է, որ իր ուսուցչի նման լինի, իսկ ծառային՝ իր տիրոջ նման։ Եթե տանտիրոջը \"Բեեղզեբուղ\" կոչեցին, ապա որքա՜ն ավելի՝ նրա ընտանիքի անդամներին։","26":"Արդ նրանցից մի՛ վախեցեք, որովհետև չկա ծածուկ բան, որ հայտնի չդառնա, և գաղտնի բան, որ չիմացվի։","27":"Ինչ որ ձեզ խավարի մեջ եմ ասում, լույսի՛ մեջ ասեք, և ինչ որ լսում եք ականջին, տանիքների վրա՛ քարոզեք։","28":"Եվ մի՛ վախեցեք նրանցից, ովքեր մարմինն են սպանում, բայց հոգին սպանել չեն կարող։ Այլ ավելի վախեցե՛ք նրանից, ով կարող է գեհենի մեջ կորստյան մատնել և՛ հոգին, և՛ մարմինը։","29":"Երկու ճնճղուկը մեկ լումայով չե՞ն վաճառվում, բայց նրանցից ոչ մեկն առանց ձեր Հոր գիտության գետնին չի ընկնում։","30":"Ձեր գլխի ամեն մի մազն էլ հաշվված է։","31":"Արդ, մի՛ վախեցեք. դուք բազում ճնճղուկներից ավելին եք։","32":"Արդ, ամեն ոք, ով ինձ մարդկանց առաջ խոստովանի, ես էլ նրան կխոստովանեմ իմ Հոր առաջ, որ երկնքում է։","33":"Իսկ ով մարդկանց առաջ ինձ ուրանա, ես էլ նրան կուրանամ իմ Հոր առաջ, որ երկնքում է։","34":"Մի՛ կարծեք, թե երկրի վրա խաղաղություն բերելու եմ եկել. չեմ եկել խաղաղություն բերելու, այլ սուր։","35":"Որովհետև եկել եմ բաժանելու որդուն իր հորից, աղջկան՝ իր մորից, հարսին՝ իր սկեսրոջից։","36":"Եվ մարդու թշնամին իր ընտանիքի անդամները կլինեն (Միք. 7.6)։","37":"Ով հորը կամ մորն ինձանից ավելի է սիրում, ինձ արժանի չէ։","38":"Եվ ով իր խաչը չի վերցնում ու չի գալիս իմ հետևից, նա ինձ արժանի չէ։","39":"Ով իր կյանքն է ապահովում, այն կկորցնի, իսկ ով ինձ համար իր կյանքը կորցնի, այն կգտնի։","40":"Ով ձեզ է ընդունում, ինձ է ընդունում, և ով ինձ է ընդունում, ինձ ուղարկողին է ընդունում։","41":"Ով մարգարեին իբրև մարգարեի է ընդունում, մարգարեի վարձ կստանա, և ով արդարին իբրև արդարի է ընդունում, արդարի վարձ կստանա։","42":"Եվ ով այս փոքրիկներից որևէ մեկին որպես իմ աշակերտի թեկուզ մեկ բաժակ սառը ջուր տա խմելու, ճշմարիտ եմ ասում ձեզ, նա իր վարձը չի կորցնի»։"},"11":{"1":"Երբ Հիսուսն իր տասներկու աշակերտներին պատվեր տալն ավարտեց, այնտեղից գնաց ուսուցանելու և քարոզելու նրանց քաղաքներում։","2":"Իսկ Հովհաննեսը, բանտում Քրիստոսի գործերի մասին լսելով, ուղարկեց իր աշակերտներին և նրանց միջոցով","3":"նրան հարցրեց. «Դո՞ւ ես նա, որ գալու էր, թե՞ ուրիշի սպասենք»։","4":"Հիսուսը պատասխանեց ու նրանց ասաց. «Գնացեք պատմե՛ք Հովհաննեսին, ինչ որ լսում ու տեսնում եք։","5":"Կույրերը տեսնում են, կաղերը՝ քայլում, բորոտները՝ մաքրվում, խուլերը՝ լսում, մեռելները՝ հարություն առնում, և աղքատներին Ավետարան է քարոզվում։","6":"Եվ երանի՜ նրան, ով ինձանով չի գայթակղվի»։","7":"Բայց երբ նրանք գնացին, Հիսուսն սկսեց Հովհաննեսի մասին ժողովրդին ասել. «Ի՞նչ տեսնելու համար անապատ ելաք՝ քամուց շարժվող մի եղե՞գ։","8":"Հապա ի՞նչ տեսնելու համար ելաք՝ փափուկ զգեստներ հագած մի մարդո՞ւ. փափուկ զգեստներ հագնողներն ահա թագավորական տներում են։","9":"Հապա ի՞նչ տեսնելու համար ելաք՝ մի մարգարեի՞. այո՛, ասում եմ ձեզ, ավելի՛ն, քան մարգարեն։","10":"Որովհետև այդ նա է, ում մասին գրված է. \"Ահա ես իմ պատգամաբերին ուղարկում եմ քո առջևից, որը քո առաջ կպատրաստի քո ճանապարհը\" (Մղք. 3.1)։","11":"Ճշմարիտ եմ ասում ձեզ. կանանցից ծնվածների մեջ Հովհաննես Մկրտչից ավելի մեծը չի եղել, բայց երկնքի արքայության մեջ ամենափոքրը նրանից մեծ է։","12":"Հովհաննես Մկրտչի հայտնվելու օրերից մինչև այժմ երկնքի արքայությունը ուժով է վերցվում, և ուժեղներն են այն հափշտակում։","13":"Որովհետև բոլոր մարգարեներն ու օրենքը մինչև Հովհաննեսն են մարգարեացել։","14":"Եվ եթե ուզում եք ընդունել, նա է Եղիան, որ գալու է։","15":"Ով լսելու ականջ ունի, թող լսի։","16":"Բայց այս սերնդին ո՞ւմ նմանեցնեմ. նման է այն երեխաներին, որոնք նստում են հրապարակներում և ձայն են տալիս իրենց ընկերներին","17":"ու ասում. \"Մենք ձեզ համար փող փչեցինք, բայց դուք չպարեցիք. մենք ձեզ համար ողբ երգեցինք, բայց դուք չողբացիք\"։","18":"Որովհետև Հովհաննեսը եկավ, ո՛չ ուտում էր, ո՛չ խմում, և ասում են. \"Նրա մեջ դև կա\"։","19":"Մարդու Որդին եկավ, ուտում է և խմում, ու ասում են. \"Ահա մի մարդ՝ ուտող և գինի խմող, մաքսավորների ու մեղավորների բարեկամն է\", և իմաստությունն արդարացվեց նրա գործերից»։","20":"Այդ ժամանակ Հիսուսը սկսեց նախատել այն քաղաքներին, որոնցում նրա հրաշքներից շատերը կատարվեցին, սակայն նրանք չապաշխարեցին։","21":"«Վա՛յ քեզ, Քորազի՛ն, վա՛յ քեզ, Բեթսայիդա՛, որովհետև եթե Տյուրոսում և Սիդովնում կատարվեին այն հրաշքները, որ ձեր մեջ կատարվեցին, վաղուց արդեն քրձով ու մոխրով ապաշխարած կլինեին։","22":"Բայց ձեզ ասում եմ. Տյուրոսի ու Սիդովնի համար դատաստանի օրն ավելի հեշտ կլինի, քան ձեզ համար։","23":"Եվ դու, Կափառնաո՛ւմ, որ մինչև երկինք ես բարձրացել, մինչև դժոխք պիտի իջնես. որովհետև եթե այն հրաշքները, որ քո մեջ են կատարվել, Սոդոմում կատարված լինեին, մինչև այսօր պահպանված կլիներ։","24":"Բայց ձեզ ասում եմ, որ սոդոմացիների երկրի համար դատաստանի օրն ավելի հեշտ կլինի, քան քեզ համար»։","25":"Այդ ժամանակ Հիսուսն ասաց. «Գոհություն եմ հայտնում քեզ, Հա՛յր, երկնքի ու երկրի Տե՛ր, որ իմաստուններից ու գիտուններից այս բաները ծածկեցիր և մանուկներին հայտնեցիր։","26":"Այո՛, Հա՛յր, որովհետև այսպես հաճելի եղավ քեզ։","27":"Ամեն բան ինձ իմ Հորից տրվեց։ Ոչ ոք Որդուն չի ճանաչում, բացի Հորից, և ոչ ոք Հորը չի ճանաչում, բացի Որդուց և նրանից, ում Որդին կուզենա հայտնել։","28":"Ինձ մո՛տ եկեք, բոլո՛ր հոգնածներ ու բեռնավորվածներ, և ես հանգիստ կտամ ձեզ։","29":"Իմ լուծը ձեզ վրա՛ վերցրեք ու ինձանի՛ց սովորեք, որովհետև ես հեզ եմ ու սրտով խոնարհ, և ձեր հոգիներին հանգստություն կգտնեք,","30":"որովհետև իմ լուծը քաղցր է, և իմ բեռը՝ թեթև»։"},"12":{"1":"Այդ ժամանակ մի շաբաթ օր Հիսուսն անցնում էր արտերի միջով։ Նրա աշակերտները քաղց զգացին ու սկսեցին հասկ պոկել և ուտել։","2":"Երբ փարիսեցիները տեսան, նրան ասացին. «Ահա քո աշակերտներն անում են այն, ինչ չի թույլատրվում անել շաբաթ օրը»։","3":"Իսկ նա ասաց նրանց. «Դուք չե՞ք կարդացել, թե Դավիթն ի՛նչ արեց, երբ ինքն ու իր հետ եղողները քաղցեցին.","4":"ինչպե՛ս Աստծու տուն մտավ ու առաջավորության հացը կերավ, որ բացի քահանաներից, չէր թույլատրվում ուտել ո՛չ իրեն, ո՛չ էլ իր հետ եղողներին։","5":"Կամ չե՞ք կարդացել Օրենքում, որ քահանաները շաբաթ օրերին տաճարում պղծում են շաբաթը, սակայն անմեղ են։","6":"Բայց ես ասում եմ ձեզ, որ այստեղ տաճարից ավելի մեծը կա։","7":"Եվ եթե գիտենայիք, թե ի՛նչ է նշանակում \"Ողորմություն եմ ուզում և ոչ թե զոհ\" (Ովս. 6.6), անմեղներին չէիք դատապարտի։","8":"Սակայն Մարդու Որդին շաբաթ օրվա տերն է»։","9":"Եվ Հիսուսը, այնտեղից հեռանալով, եկավ նրանց ժողովարանը։","10":"Եվ ահա այնտեղ ձեռքը չորացած մի մարդ կար։ Հիսուսին ամբաստանելու համար նրան հարցրին՝ ասելով. «Թույլատրվո՞ւմ է շաբաթ օրը բժշկություն անել»։","11":"Նա պատասխանեց նրանց. «Ձեզանից ո՞վ է այն մարդը, որ եթե մի ոչխար ունենա, և այն շաբաթ օրը փոսն ընկնի, նրան չի բռնի ու վեր հանի։","12":"Արդ, մարդը որքա՜ն առավել է ոչխարից։ Ուստի շաբաթ օրը բարիք գործելը թույլատրելի է»։","13":"Այդ ժամանակ Հիսուսն այդ մարդուն ասաց. «Ձեռքդ մեկնի՛ր»։ Նա չորացած ձեռքը մեկնեց, և այն մյուսի նման առողջ դարձավ։","14":"Իսկ փարիսեցիները դուրս ելան ու նրա դեմ խորհրդակցեցին, թե ինչպե՛ս նրան կորստյան մատնեն։","15":"Երբ Հիսուսն իմացավ, այնտեղից հեռացավ։ Եվ ժողովրդի մեծ բազմություն գնաց նրա հետևից, ու նա բոլորին բժշկեց։","16":"Եվ պատվիրեց նրանց, որ իր մասին չհայտնեն,","17":"որպեսզի կատարվեր Եսայի մարգարեի միջոցով ասվածը.","18":"«Ահա իմ ծառան, որին ընտրեցի, իմ սիրելին, որի նկատմամբ իմ հոգին բարեհաճ եղավ. իմ Հոգին նրա վրա կդնեմ, և նա հեթանոսներին կհայտնի դատաստանի մասին։","19":"Նա չի հակառակվի, չի աղաղակի, և ոչ ոք հրապարակներում նրա ձայնը չի լսի։","20":"Ջախջախված եղեգը չի փշրի և առկայծող պատրույգը չի հանգցնի, մինչև որ դատաստանը հաղթանակի հասցնի։","21":"Եվ հեթանոսները հույսը կդնեն նրա անվան վրա» (Ես. 42.1-4)։","22":"Այդ ժամանակ Հիսուսի մոտ մի կույր ու համր դիվահար բերվեց, և նա բժշկեց նրան, այնպես որ կույր ու համրը և՛ տեսավ, և՛ խոսեց։","23":"Ժողովրդի ողջ բազմությունը զարմացավ ու ասում էր. «Մի՞թե սա է Դավթի որդին»։","24":"Սակայն փարիսեցիները լսեցին և ասացին. «Դա դևերին այլ կերպ չի հանում, եթե ոչ դևերի իշխան Բեեղզեբուղի միջոցով»։","25":"Հիսուսը, նրանց մտքերը հասկանալով, ասաց. «Ամեն թագավորություն, որ իր մեջ մասնատված է, կավերվի, և ինքն իր մեջ մասնատված ամեն քաղաք կամ տուն կանգուն չի մնա։","26":"Եթե սատանան սատանային հանում է, ինքն իր մեջ բաժանվում է, արդ նրա թագավորությունն ինչպե՞ս կանգուն կմնա։","27":"Եվ եթե ես դևերին Բեեղզեբուղի միջոցով եմ հանում, ապա ձեր որդինե՞րն ինչով են հանում։ Դրա համար էլ նրա՛նք ձեր դատավորները կլինեն։","28":"Իսկ եթե ես Աստծու Հոգով եմ դևերին հանում, ուրեմն Աստծու արքայությունը հասել է ձեզ վրա։","29":"Կամ ինչպե՞ս կարող է մեկը հզոր մարդու տունը մտնել ու նրա ունեցածը հափշտակել, եթե նախ այդ հզորին չկապի և հետո նրա տունը կողոպտի։","30":"Ով ինձ հետ չէ, ինձ հակառակ է, և ով ինձ հետ չի հավաքում, ցրում է։","31":"Դրա համար ասում եմ ձեզ. ամեն մեղք ու հայհոյանք մարդկանց կներվեն, բայց Հոգու դեմ հայհոյանքը մարդկանց չի ներվի։","32":"Ով Մարդու Որդու դեմ որևէ բան ասի, նրան կներվի, բայց ով Սուրբ Հոգու դեմ ասի, նրան չի ներվի ո՛չ այս աշխարհում, ո՛չ էլ հանդերձյալում։","33":"Եթե ծառը լավը համարեք, նրա պտուղը ևս լավը կլինի, իսկ եթե ծառը վատը համարեք, նրա պտուղը ևս վատը կլինի, որովհետև ծառն իր պտղից է ճանաչվում։","34":"Իժերի՛ ծնունդներ, դուք ինչպե՞ս կարող եք բարի խոսել, երբ չար եք. որովհետև բերանը սրտի լիությունից է խոսում։","35":"Բարի մարդն իր սրտի բարի գանձից է բարիքներ հանում, իսկ չար մարդը չար գանձից է չարիք հանում։","36":"Բայց ասում եմ ձեզ, որ ամեն դատարկ խոսքի համար, որ մարդիկ խոսում են, դատաստանի օրը հաշիվ պիտի տան։","37":"Որովհետև քո խոսքերից պիտի արդարացվես և քո խոսքերից պիտի դատապարտվես»։","38":"Այդ ժամանակ դպիրներից ու փարիսեցիներից ոմանք Հիսուսին պատասխանեցին՝ ասելով. «Վարդապե՛տ, ուզում ենք քեզանից մի նշան տեսնել»։","39":"Հիսուսը պատասխանեց ու նրանց ասաց. «Չար ու շնացող մի սերունդ նշան է ուզում, բայց նրան նշան չի տրվի, բացի Հովնան մարգարեի նշանից։","40":"Որովհետև ինչպես Հովնանը երեք օր ու երեք գիշեր մնաց կետի փորում, այնպես էլ Մարդու Որդին երեք օր ու երեք գիշեր կմնա երկրի սրտում։","41":"Նինվեացիները դատաստանին այս սերնդի հետ վեր կկենան և կդատապարտեն նրան, քանի որ նրանք Հովնանի քարոզությամբ ապաշխարեցին, իսկ ահա այստեղ Հովնանից ավելի մեծն է։","42":"Հարավի թագուհին դատաստանին այս սերնդի հետ վեր կկենա և կդատապարտի նրան, որովհետև երկրի մյուս ծայրից եկավ Սողոմոնի իմաստությունը լսելու, իսկ ահա այստեղ Սողոմոնից ավելի մեծը կա։","43":"Երբ պիղծ ոգին դուրս է ելնում մարդու միջից, շրջում է անջրդի վայրերում, հանգիստ է որոնում, բայց չի գտնում։","44":"Այդ ժամանակ ասում է. \"Վերադառնամ իմ տունը, որտեղից դուրս ելա\"։ Եվ գալիս, այն գտնում է դատարկված, մաքրված ու հարդարված։","45":"Այդ ժամանակ գնում, վերցնում է իր հետ իրենից է՛լ ավելի չար յոթ ուրիշ ոգիների և մտնում, բնակվում է այնտեղ։ Եվ այդ մարդու վերջն ավելի վատ է լինում, քան նախկինում էր։ Այդպես կլինի նաև այս չար սերնդի հետ»։","46":"Մինչ Հիսուսը խոսում էր ժողովրդի հետ, ահա նրա մայրն ու նրա եղբայրները կանգնել էին դրսում և ուզում էին խոսել նրա հետ։","47":"Եվ մեկն ասաց նրան. «Ահա մայրդ ու եղբայրներդ, դրսում կանգնած, ուզում են խոսել քեզ հետ»։","48":"Նա պատասխանեց իրեն ասողին ու ասաց. «Ո՞վ է իմ մայրը, և ովքե՞ր են իմ եղբայրները»։","49":"Եվ իր ձեռքը դեպի իր աշակերտները մեկնելով՝ ասաց. «Ահա իմ մայրն ու իմ եղբայրները։","50":"Որովհետև ով կատարում է իմ Հոր կամքը, որ երկնքում է, նա է իմ եղբայրը, քույրը և մայրը»։"},"13":{"1":"Այդ օրը Հիսուսը տնից դուրս եկավ և նստեց լճի եզերքին։","2":"Նրա շուրջը ժողովրդի այնպիսի բազմություն հավաքվեց, որ նա նավակի մեջ նստեց, իսկ ամբողջ ժողովուրդը լճի եզերքին կանգնած մնաց։","3":"Եվ նրանց հետ շատ բաներ առակներով էր խոսում՝ ասելով.","4":"«Ահա սերմնացանը ելավ սերմանելու։ Երբ նա սերմանում էր, մի քանի սերմնահատիկ ճանապարհի եզերքին ընկան, և երկնքի թռչունները եկան ու դրանք կերան։","5":"Իսկ ուրիշները քարքարոտ տեղ ընկան, որտեղ շատ հող չկար, և իսկույն բուսնեցին հողի սակավության պատճառով։","6":"Բայց երբ արևը ծագեց, վառվեցին, և որովհետև արմատ չունեին, չորացան։","7":"Ուրիշները փշերի մեջ ընկան, և փշերը բարձրացան ու դրանց խեղդեցին։","8":"Իսկ ուրիշներն էլ բարեբեր հողի վրա ընկան ու պտուղ տվեցին. մեկը՝ հարյուրապատիկ, մեկը՝ վաթսունապատիկ, և մեկը՝ երեսնապատիկ։","9":"Ով լսելու ականջ ունի, թող լսի»։","10":"Աշակերտները մոտեցան և նրան ասացին. «Ինչո՞ւ ես նրանց հետ առակներով խոսում»։","11":"Իսկ նա պատասխանեց ու ասաց նրանց. «Քանի որ ձեզ է տրված իմանալ երկնքի արքայության խորհուրդները, իսկ նրանց տրված չէ։","12":"Որովհետև ով ունի, նրան կտրվի ու կավելացվի, իսկ ով չունի, նրանից ունեցածն էլ կվերցվի։","13":"Դրա՛ համար եմ նրանց հետ առակներով խոսում, որ նայելով չեն տեսնում և ականջ դնելով չեն լսում ու չեն հասկանում։","14":"Եվ նրանցով է իրականանում Եսայու մարգարեությունը, որ ասում է. \"Շարունակ կլսեք ու չեք հասկանա, անդադար կնայեք ու չեք տեսնի։","15":"Որովհետև այս ժողովրդի սիրտը կարծրացավ, և իրենց ականջներով ծանր լսեցին և իրենց աչքերը փակեցին, որ երբեք աչքերով չտեսնեն և ականջներով չլսեն և սրտով չիմանան ու դարձի չգան, և նրանց չբժշկեմ\" (Ես. 6.9-10)։","16":"Բայց երանի՜ ձեր աչքերին, որ տեսնում են, և ձեր ականջներին, որ լսում են։","17":"Որովհետև ճշմարիտ եմ ասում ձեզ, բազում մարգարեներ ու արդարներ ցանկացան տեսնել այն, ինչ դուք եք տեսնում, բայց չտեսան, և լսել այն, ինչ դուք եք լսում, բայց չլսեցին։","18":"Արդ դուք լսե՛ք սերմնացանի առակը։","19":"Ամեն ոք, ով լսում է արքայության խոսքը, բայց չի հասկանում, գալիս է չարը և հափշտակում նրա սրտի մեջ սերմանվածը. ճանապարհի եզերքին սերմանվածը սա է։","20":"Քարքարոտ վայրում սերմանվածը նա է, ով խոսքը լսելիս իսկույն ուրախությամբ ընդունում է այն,","21":"բայց քանի որ իր մեջ արմատ չունի, այլ ժամանակավոր է, ապա երբ այդ խոսքի պատճառով նեղություն կամ հալածանք է լինում, իսկույն գայթակղվում է։","22":"Փշերի մեջ սերմանվածը նա է, ով լսում է խոսքը, բայց այս աշխարհի հոգսերն ու հարստության պատրանքները խեղդում են այդ խոսքը, և այն անպտուղ է լինում։","23":"Իսկ բարեբեր հողի մեջ սերմանվածը նա է, ով լսում է խոսքը և հասկանում ու պտուղ է տալիս. մեկը՝ հարյուրապատիկ, մեկը՝ վաթսունապատիկ, և մեկը՝ երեսնապատիկ»։","24":"Հիսուսը նրանց մեկ այլ առակ էլ պատմեց ու ասաց. «Երկնքի արքայությունը նման է մի մարդու, որն իր արտում լավ սերմ ցանեց։","25":"Երբ մարդիկ քնած էին, նրա թշնամին եկավ և ցորենի մեջ որոմ ցանեց ու գնաց։","26":"Երբ խոտը բուսնեց ու պտուղ տվեց, երևաց նաև որոմը։","27":"Տանտիրոջ ծառաները մոտեցան նրան և ասացին. \"Տե՛ր, չէ՞ որ արտիդ մեջ լավ սերմ ցանեցիր։ Ուրեմն այդ որոմը որտեղի՞ց է\"։","28":"Իսկ նա ասաց նրանց. \"Թշնամի մարդն է դա արել\"։ Ծառաները նրան ասացին. \"Հիմա ուզո՞ւմ ես՝ գնանք, դրանք քաղհանենք\"։","29":"Նա ասաց. \"Ո՛չ, որոմը քաղելիս միգուցե ցորենն էլ դրանց հետ արմատախիլ անեք։","30":"Թողե՛ք, որ մինչև հունձքը երկուսը միասին աճեն, և հունձքի ժամանակ հնձողներին կասեմ. \"Նախ որո՛մը քաղեք ու խրձե՛ր կապեք այրելու համար, իսկ ցորենը հավաքե՛ք իմ շտեմարանի մեջ\"»։","31":"Նրանց մի առակ ևս պատմեց ու ասաց. «Երկնքի արքայությունը նման է մանանեխի հատիկի, որ մի մարդ վերցրեց և իր արտի մեջ ցանեց։","32":"Այն բոլոր սերմերից ավելի փոքր է, բայց երբ աճում է, բոլոր բույսերից ավելի մեծ է լինում և ծառ է դառնում, այնպես որ երկնքի թռչունները գալիս են ու նրա ճյուղերին հանգիստ առնում»։","33":"Հիսուսը մեկ այլ առակ էլ ասաց նրանց. «Երկնքի արքայությունը նման է թթխմորի, որ մի կին վերցրեց և երեք չափ ալյուրի մեջ դրեց, մինչև որ ամբողջը խմորվեց»։","34":"Այս ամենը Հիսուսը ժողովրդին առակներով ասաց. նրանց հետ առանց առակի չէր խոսում,","35":"որպեսզի իրականանար մարգարեի միջոցով ասվածը. «Առակներով կբացեմ իմ բերանը, կբացահայտեմ աշխարհի սկզբից ի վեր ծածկված բաները» (Սաղ. 78.2)։","36":"Այդ ժամանակ Հիսուսը թողեց ժողովրդին և տուն եկավ։ Աշակերտները մոտեցան նրան ու ասացին. «Մեկնի՛ր մեզ արտի որոմների առակը»։","37":"Նա պատասխանեց ու նրանց ասաց. «Լավ սերմը ցանողը Մարդու Որդին է,","38":"իսկ արտն աշխարհն է։ Լավ սերմը նրանք են, որոնք արքայության որդիներն են, իսկ որոմը չարի որդիներն են։","39":"Թշնամին, որ այն սերմանեց, սատանան է, հունձքն էլ աշխարհի վերջն է, իսկ հնձողները հրեշտակներն են։","40":"Արդ, ինչպես որոմը հավաքում են ու կրակով այրում, այնպես էլ աշխարհի վերջում է լինելու։","41":"Մարդու Որդին կուղարկի իր հրեշտակներին, որոնք կհավաքեն նրա արքայությունից բոլոր գայթակղություններն ու անօրենություններ գործողներին","42":"և նրանց կգցեն կրակի հնոցը. այնտեղ կլինի լաց և ատամների կրճտոց։","43":"Այդ ժամանակ արդարները արեգակի պես կփայլեն իրենց Հոր արքայության մեջ։ Ով որ լսելու ականջ ունի, թող լսի։","44":"Երկնքի արքայությունը նման է արտի մեջ թաքցված գանձի, որը մի մարդ գտել է և թաքցրել։ Նա ուրախությունից գնում և վաճառում է իր ամբողջ ունեցածն ու գնում է այդ արտը։","45":"Դարձյալ, երկնքի արքայությունը նման է մի վաճառականի, որը գեղեցիկ մարգարիտներ է որոնում","46":"և մի թանկագին մարգարիտ գտնելով՝ գնում վաճառում է իր ամբողջ ունեցածը և գնում է այն։","47":"Դարձյալ, երկնքի արքայությունը նման է ծովը նետված ուռկանի, որ ամեն տեսակ ձուկ է հավաքում,","48":"և երբ լցվեց, ցամաք հանեցին և նստեցին, լավերն ամանների մեջ հավաքեցին, իսկ վատերը դեն նետեցին։","49":"Այսպես է լինելու նաև աշխարհի վերջում. հրեշտակները դուրս կելնեն և արդարների միջից չարերին կզատեն","50":"ու նրանց կրակի հնոցը կգցեն։ Այնտեղ կլինի լաց և ատամների կրճտոց»։","51":"Հիսուսը նրանց ասաց. «Այդ բոլորը հասկացա՞ք»։ Նրան ասացին. «Այո՛, Տե՛ր»։","52":"Նա ասաց նրանց. «Դրա համար ամեն դպիր, որ երկնքի արքայությանն է աշակերտել, նման է տանուտեր մարդու, որն իր գանձատուփից նոր ու հին իրեր է հանում»։","53":"Երբ Հիսուսն այս առակներն ավարտեց, այդտեղից հեռացավ։","54":"Նա եկավ իր հայրենի քաղաքը և ուսուցանում էր նրանց ժողովարանում, այնպես որ նրանք զարմանում էին ու ասում. «Որտեղի՞ց սրան այս իմաստությունն ու հրաշագործ զորությունը։","55":"Սա հյուսնի որդին չէ՞, սրա մայրը Մարիամ չի՞ կոչվում, իսկ եղբայրները՝ Հակոբոս, Հովսես, Սիմոն և Հուդա։","56":"Սրա քույրերը բոլորը մեզ մոտ չե՞ն։ Որտեղի՞ց սրան այս ամենը»։","57":"Եվ գայթակղվում էին նրանով։ Իսկ Հիսուսը նրանց ասաց. «Չկա անարգված մարգարե, եթե ոչ իր գավառում ու իր տանը»։","58":"Եվ Հիսուսը նրանց անհավատության պատճառով այնտեղ շատ հրաշքներ չգործեց։"},"14":{"1":"Այդ ժամանակ Հերովդես չորրորդապետը լսեց Հիսուսի համբավը","2":"և իր ծառաներին ասաց. «Նա Հովհաննես Մկրտիչն է. մեռելներից հարություն է առել, և դրա համար նրա միջոցով հրաշքներ են կատարվում»։","3":"Հերովդեսը ձերբակալել էր Հովհաննեսին, նրան կապել ու բանտարկել իր եղբոր՝ Փիլիպպոսի կնոջ՝ Հերովդիայի պատճառով,","4":"քանի որ Հովհաննեսը Հերովդեսին ասում էր. «Քեզ չի թույլատրվում նրան կնության առնել»։","5":"Եվ ցանկանում էր նրան սպանել, բայց ժողովրդից վախենում էր, որովհետև Հովհաննեսին որպես մարգարեի էին ընդունում։","6":"Հերովդեսի ծննդյան օրը Հերովդիայի աղջիկը հրավիրյալների առաջ պարեց, և Հերովդեսին դա դուր եկավ։","7":"Նա երդմամբ խոստացավ աղջկան տալ այն, ինչ որ ուզեր։","8":"Իսկ նա, նախապես իր մորից խրատված լինելով, ասաց. «Տո՛ւր ինձ այստեղ՝ սկուտեղի վրա, Հովհաննես Մկրտչի գլուխը»։","9":"Թագավորը տրտմեց, բայց իր երդման և սեղանակիցների պատճառով հրամայեց, որ նրան տրվի։","10":"Եվ մարդ ուղարկեց՝ բանտում Հովհաննեսին գլխատելու։","11":"Նրա գլուխն սկուտեղի վրա բերվեց և աղջկան տրվեց, նա էլ այն իր մորը տարավ։","12":"Հովհաննեսի աշակերտները եկան, վերցրին մարմինն ու թաղեցին, ապա եկան պատմեցին Հիսուսին։","13":"Երբ Հիսուսը լսեց, այնտեղից նավով միայնակ մի ամայի տեղ գնաց։ Երբ ժողովուրդը լսեց, քաղաքներից ոտքով նրա հետևից գնաց։","14":"Հիսուսը, ցամաք ելնելով, շատ ժողովուրդ տեսավ, նրանց գթաց ու հիվանդներին բժշկեց։","15":"Երբ երեկո եղավ, աշակերտները մոտեցան նրան ու ասացին. «Այս տեղն ամայի է, ժամն էլ ուշ է. արձակի՛ր ժողովրդին, որպեսզի գյուղերը գնան և իրենց համար ուտելիք առնեն»։","16":"Հիսուսն ասաց նրանց. «Կարիք չկա, որ գնան. դո՛ւք նրանց ուտելիք տվեք»։","17":"Նրանք ասացին. «Մենք այստեղ ոչինչ չունենք, բացի հինգ հացից ու երկու ձկից»։","18":"Իսկ նա ասաց. «Դրանք այստե՛ղ՝ ինձ մո՛տ բերեք»։","19":"Հիսուսը կարգադրեց, որ ժողովուրդը խոտերի վրա նստի։ Նա, վերցնելով հինգ հացն ու երկու ձուկը, երկինք նայեց, օրհնեց, մաս-մաս արեց, հացերն աշակերտներին տվեց, աշակերտներն էլ՝ ժողովրդին։","20":"Բոլորն էլ կերան ու կշտացան։ Եվ տասներկու սակառ լեցուն ավելացած կտորներ վերցրին։","21":"Իսկ ուտողները հինգ հազարի չափ մարդ էին, բացի կանանցից և երեխաներից։","22":"Հիսուսն իսկույն իր աշակերտներին ստիպեց, որ նավ նստեն ու իրենից առաջ լճի մյուս կողմն անցնեն, մինչև ինքն այդ ժողովրդին արձակի։","23":"Ժողովրդին արձակելուց հետո բարձրացավ լեռը՝ առանձին աղոթելու։ Երբ երեկո եղավ, Հիսուսն այնտեղ մենակ էր,","24":"իսկ նավը ցամաքից բավականին հեռու էր և ալիքներից տարուբերվում էր, որովհետև քամին հակառակ կողմից էր։","25":"Գիշերվա չորրորդ պահին Հիսուսը, լճի վրա քայլելով, նրանց մոտ եկավ։","26":"Երբ աշակերտները նրան տեսան լճի վրայով քայլելիս, շփոթվեցին ու ասացին, թե ուրվական է, և վախից աղաղակեցին։","27":"Հիսուսն իսկույն խոսեց նրանց հետ ու ասաց. «Քաջալերվե՛ք, ես եմ, մի՛ վախեցեք»։","28":"Պետրոսը նրան ասաց. «Տե՛ր, եթե դու ես, հրամայի՛ր ինձ ջրի վրայով քեզ մոտ գալ»։","29":"Իսկ նա ասաց՝ ե՛կ։ Եվ Պետրոսը, նավից իջնելով, քայլեց ջրի վրայով և Հիսուսի մոտ եկավ։","30":"Սակայն սաստիկ քամին տեսնելով՝ վախեցավ և երբ սկսեց սուզվել, աղաղակեց ու ասաց. «Տե՛ր, փրկի՛ր ինձ»։","31":"Հիսուսն իսկույն ձեռքը մեկնեց, բռնեց նրան և ասաց. «Թերահավա՛տ, ինչո՞ւ երկմտեցիր»։","32":"Երբ նրանք նավ մտան, քամին հանդարտվեց։","33":"Նավի վրա եղողները երկրպագեցին նրան ու ասացին. «Իսկապես դու Աստծու Որդին ես»։","34":"Նրանք, լճի մյուս կողմն անցնելով, Գեննեսարեթի գավառ եկան։","35":"Տեղաբնակները, Հիսուսին ճանաչելով, մարդ ուղարկեցին ամբողջ գավառով մեկ, և բոլոր հիվանդներին նրա մոտ բերեցին։","36":"Եվ աղաչում էին նրան, որ գոնե նրա հագուստի քղանցքին դիպչեն։ Եվ ովքեր դիպան, բժշկվեցին։"},"15":{"1":"Այդ ժամանակ Հիսուսին մոտեցան դպիրներն ու փարիսեցիները և ասացին.","2":"«Իսկ դուք ինչո՞ւ եք անտեսում Աստծու պատվիրանները ձեր ավանդույթի պատճառով, որովհետև երբ հաց են ուտում, իրենց ձեռքերը չեն լվանում»։","3":"Իսկ նա պատասխանեց ու ասաց նրանց. «Հապա դո՞ւք ինչու եք ձեր ավանդույթների պատճառով Աստծու պատվիրաններն անտեսում։","4":"Որովհետև Աստված ասել է. \"Պատվի՛ր քո հորն ու մորը\" (Ելք 20.12, Բ Օր. 5.16) և \"Ով իր հորը կամ մորը չարախոսի, մահվան կդատապարտվի\" (Ելք 21.17, Ղևտ. 20.9)։","5":"Իսկ դուք ասում եք. \"Ով իր հորը կամ մորն ասի՝ “Այն օգնությունը, որ ինձնից պիտի ստանայիր, Աստծուն եմ ընծայել”,","6":"և կարող է իր հորը կամ իր մորը չպատվել\"։ Ձեր ավանդույթի պատճառով խախտում եք Աստծու պատվիրանը։","7":"Կեղծավորնե՛ր, Եսային ձեր մասին լավ է մարգարեացել՝ ասելով.","8":"\"Այս ժողովուրդն ինձ շրթունքներով է պատվում, իսկ նրանց սիրտն ինձանից շատ է հեռացել։","9":"Զուր են ինձ պաշտում, երբ ուսուցանում են մարդկանց կողմից հորինված պատվիրաններ\" (Ես. 29.13)»։","10":"Եվ Հիսուսը, ժողովրդին իր մոտ կանչելով, ասաց. «Լսե՛ք ու հասկացե՛ք.","11":"մարդուն պղծում է ոչ թե այն, ինչ նրա բերանն է մտնում, այլ այն, ինչ նրա բերանից է դուրս գալիս»։","12":"Այդ ժամանակ նրա աշակերտները մոտեցան և նրան ասացին. «Գիտե՞ս, որ երբ փարիսեցիներն այդ խոսքը լսեցին, գայթակղվեցին»։","13":"Նա պատասխան տվեց ու ասաց. «Ամեն տունկ, որ իմ երկնավոր Հայրը չի տնկել, արմատախիլ կարվի։","14":"Թողե՛ք նրանց. նրանք կույր են և կույրերի առաջնորդներ։ Երբ կույրը կույրին առաջնորդի, երկուսն էլ փոսը կընկնեն»։","15":"Այդժամ Պետրոսը Հիսուսին ասաց. «Բացատրի՛ր մեզ այս առակը»։","16":"Իսկ Հիսուսն ասաց. «Դո՞ւք էլ դեռ չեք հասկանում։","17":"Չե՞ք հասկանում, որ այն ամենը, ինչ բերանն է մտնում, որովայնի մեջ է գնում, ապա արտաքնոց գցվում։","18":"Սակայն այն, ինչ բերանից է ելնում, սրտից է գալիս, և դա՛ է մարդուն պղծում։","19":"Որովհետև սրտից դուրս են գալիս չար մտքեր, սպանություններ, շնություններ, պոռնկություններ, գողություններ, սուտ վկայություններ, հայհոյություններ։","20":"Սրանք են մարդուն պղծում, բայց անլվա ձեռքերով ուտելը մարդուն չի պղծում»։","21":"Հիսուսն այնտեղից դուրս ելավ և Տյուրոսի ու Սիդովնի կողմերը գնաց։","22":"Եվ ահա քանանացի մի կին, որ գալիս էր այն սահմաններից, աղաղակում էր ու ասում նրան. «Ողորմի՛ր ինձ, Տե՛ր, Դավթի՛ որդի, իմ աղջիկը տառապում է դևից»։","23":"Սակայն Հիսուսը նույնիսկ մի բառ նրան չպատասխանեց։ Նրա աշակերտները մոտեցան և խնդրում էին նրան՝ ասելով. «Արձակի՛ր նրան, որովհետև աղաղակում է մեր հետևից»։","24":"Հիսուսը պատասխանեց ու ասաց. «Ես ուղարկվել եմ միայն Իսրայելի տան կորած ոչխարների մոտ»։","25":"Իսկ կինը եկել և նրան երկրպագում էր՝ ասելով. «Տե՛ր, օգնի՛ր ինձ»։","26":"Նա պատասխանեց ու ասաց. «Լավ չէ երեխաների հացն առնել ու շների առաջ նետել»։","27":"Իսկ նա ասաց. «Այո՛, Տե՛ր, սակայն շներն էլ իրենց տերերի սեղանից թափված փշրանքներով են կերակրվում»։","28":"Այդ ժամանակ Հիսուսը պատասխանեց նրան ու ասաց. «Ո՛վ կին, մեծ է քո հավատը. թող քեզ քո ուզածի պես լինի»։ Եվ նույն պահին նրա աղջիկը բժշկվեց։","29":"Հիսուսը, հեռանալով այնտեղից, եկավ Գալիլեայի լճի մոտ և լեռը բարձրանալով՝ նստեց այնտեղ։","30":"Եվ նրան ժողովրդի մեծ բազմություն մոտեցավ. նրանք իրենց հետ ունեին կաղերի, կույրերի, համրերի, հաշմանդամների և ուրիշ շատերի։ Նրանց Հիսուսի ոտքերի առջև դրեցին, և նա բժշկեց նրանց,","31":"այնպես որ ժողովուրդը զարմանում էր՝ տեսնելով համրերին խոսելիս, հաշմանդամներին՝ առողջ, կաղերին՝ քայլելիս, իսկ կույրերին՝ տեսնելիս, և փառաբանում էին Իսրայելի Աստծուն։","32":"Հիսուսն իր մոտ կանչեց աշակերտներին և ասաց. «Խղճում եմ այս ժողովրդին, որովհետև արդեն երեք օր է՝ ինձ մոտ են և ուտելու ոչինչ չունեն։ Չեմ ուզում նրանց քաղցած արձակել. գուցե ճանապարհին նվաղեն»։","33":"Աշակերտները նրան ասացին. «Այս ամայի վայրում մեզ որտեղի՞ց այնքան հաց, որ այսքան ժողովուրդ կշտանա»։","34":"Հիսուսը նրանց ասաց. «Քանի՞ հաց ունեք»։ Նրանք ասացին. «Յոթ և մի քանի փոքր ձուկ»։","35":"Հիսուսը ժողովրդին կարգադրեց, որ նստեն գետնին։","36":"Նա վերցրեց այն յոթ հացն ու ձկները, գոհություն հայտնեց, մաս-մաս արեց և կտրեց ու աշակերտներին տվեց, աշակերտներն էլ՝ ժողովրդին։","37":"Բոլորը կերան ու կշտացան. և ավելացած կտորներով յոթ զամբյուղ լցրեցին։","38":"Ովքեր կերան, չորս հազար տղամարդիկ էին, կանանցից և երեխաներից բացի։","39":"Հիսուսը բազմությանն արձակելուց հետո նավ նստեց ու Մագդաղայի սահմանները եկավ։"},"16":{"1":"Հիսուսի մոտ եկան փարիսեցիներն ու սադուկեցիները և նրան փորձելու համար խնդրում էին, որ իրենց երկնային մի նշան ցույց տա։","2":"Իսկ նա պատասխանեց ու ասաց նրանց. «Երեկոյան ասում եք. \"Լավ եղանակ կլինի, որովհետև երկինքը շառագունել է\"։","3":"Իսկ առավոտյան ասում եք. \"Այսօր վատ եղանակ կլինի, որովհետև երկինքը մթնել և շառագունել է\"։ Երկնքի նշանները քննել գիտեք, իսկ ժամանակների նշանները հասկանալ չե՞ք կարողանում։","4":"Չար ու շնացող մի սերունդ նշան է ուզում, սակայն նրան նշան չի տրվի, բացի Հովնան մարգարեի նշանից»։ Եվ թողեց նրանց ու հեռացավ։","5":"Երբ աշակերտները լճի մյուս ափը գնացին, մոռացան հաց վերցնել։","6":"Հիսուսը նրանց ասաց. «Տեսե՛ք և զգուշացե՛ք փարիսեցիների ու սադուկեցիների խմորից»։","7":"Նրանք իրենց մեջ մտածում էին ու ասում. «Հաց չենք վերցրել»։","8":"Հիսուսը հասկացավ այդ և ասաց. «Թերահավատնե՛ր, ինչո՞ւ եք ձեր մեջ մտածում, թե հաց չեք վերցրել։","9":"Դեռ չե՞ք հասկացել կամ չե՞ք հիշում հինգ հազար մարդու համար այն հինգ հացի մասին կամ թե քանի՛ կողով վերցրիք,","10":"ոչ էլ այն յոթ հացը չորս հազար մարդու համար կամ թե քանի՛ զամբյուղ վերցրիք։","11":"Ինչպե՞ս չեք հասկանում, որ հացի համար ձեզ չասացի, որ փարիսեցիների և սադուկեցիների խմորից զգուշանաք»։","12":"Այն ժամանակ հասկացան, որ հացի խմորից զգուշանալու մասին չէր ասել, այլ փարիսեցիների և սադուկեցիների աղանդից զգուշանալու։","13":"Երբ Հիսուսը Փիլիպպյան Կեսարիայի կողմերը եկավ, հարցրեց իր աշակերտներին և ասաց. «Մարդիկ ի՞նչ են ասում իմ մասին. ո՞վ է Մարդու Որդին»։","14":"Իսկ նրանք ասացին. «Ոմանք ասում են՝ Հովհաննես Մկրտիչն է, մյուսները՝ Եղիան, ուրիշներն էլ՝ Երեմիան կամ մարգարեներից մեկը»։","15":"Նրանց ասաց. «Իսկ դո՞ւք ինչ եք ասում իմ մասին. ո՞վ եմ»։","16":"Սիմոն Պետրոսը պատասխանեց ու ասաց. «Դու Քրիստոսն ես՝ կենդանի Աստծու Որդին»։","17":"Հիսուսը պատասխանեց ու ասաց նրան. «Երանի՜ քեզ, Սիմո՛ն, Հովնանի՛ որդի, որովհետև ոչ թե մարմինն ու արյունը հայտնեցին քեզ, այլ իմ Հայրը, որ երկնքում է։","18":"Ես էլ քեզ ասում եմ, որ դու Պետրոս ես, և այդ վեմի վրա եմ կառուցելու իմ եկեղեցին, և դժոխքի դռները նրան չեն կարողանա հաղթել։","19":"Ես քեզ եմ տալու երկնքի արքայության բանալիները, և ինչ որ երկրի վրա կապես, կապված կլինի երկնքում, և ինչ որ երկրի վրա արձակես, արձակված կլինի երկնքում»։","20":"Այդ ժամանակ Հիսուսն իր աշակերտներին պատվիրեց, որ ոչ ոքի չասեն, թե ինքն է Քրիստոսը։","21":"Դրանից հետո Հիսուսն սկսեց հայտնել աշակերտներին, որ ինքը պետք է Երուսաղեմ գնա, ծերերից, քահանայապետներից, դպիրներից շատ չարչարանքներ կրի, սպանվի ու երրորդ օրը հարություն առնի։","22":"Պետրոսը, նրան մի կողմ տանելով, սկսեց նրան հանդիմանել ու ասել. «Քա՛վ լիցի, Տե՛ր, թող քեզ այդպիսի բան չպատահի»։","23":"Եվ նա դարձավ Պետրոսին ու ասաց. «Հետև՛ս գնա, սատանա՛, դու ինձ համար գայթակղություն ես, որովհետև դու խորհում ես ոչ թե այնպես, ինչպես Աստված է կամենում, այլ այնպես, ինչպես մարդիկ»։","24":"Այդ ժամանակ Հիսուսն իր աշակերտներին ասաց. «Եթե մեկը կամենում է իմ հետևից գալ, թող ուրանա ինքն իրեն, վերցնի իր խաչը և գա իմ հետևից։","25":"Որովհետև ով ուզենա փրկել իր կյանքը, կկորցնի այն, իսկ ով իր կյանքը կորցնի ինձ համար, կգտնի այն։","26":"Մարդուն ի՞նչ օգուտ, եթե ամբողջ աշխարհը շահի, բայց իր կյանքը կորցնի, կամ մարդն ի՞նչ փրկագին կտա։","27":"Որովհետև Մարդու Որդին գալու է իր Հոր փառքով, իր հրեշտակների հետ և այդ ժամանակ ամեն մեկին հատուցելու է ըստ իր գործերի։","28":"Ճշմարիտ եմ ասում ձեզ. այստեղ կանգնածներից ոմանք մահ չեն ճաշակելու, մինչև Մարդու Որդուն իր թագավորությամբ գալիս չտեսնեն»։"},"17":{"1":"Վեց օր հետո Հիսուսը Պետրոսին, Հակոբոսին ու նրա եղբայր Հովհաննեսին իր հետ վերցրեց և նրանց առանձին մի բարձր լեռ հանեց։","2":"Եվ նրանց առաջ այլակերպվեց. նրա դեմքն արեգակի պես փայլեց, իսկ զգեստները լույսի պես սպիտակ դարձան։","3":"Եվ ահա նրանց երևացին Մովսեսն ու Եղիան, որոնք խոսում էին Հիսուսի հետ։","4":"Պետրոսը Հիսուսին ասաց. «Տե՛ր, լավ է, որ մենք այստեղ մնանք։ Եթե կամենաս, այստեղ երեք տաղավարներ կպատրաստենք. մեկը՝ քեզ համար, մեկը՝ Մովսեսի, մեկն էլ՝ Եղիայի»։","5":"Մինչ նա խոսում էր, մի լուսավոր ամպ հովանի եղավ նրանց վրա։ Ամպից մի ձայն լսվեց, որ ասում էր. «Դա՛ է իմ սիրելի Որդին, որն ունի իմ բարեհաճությունը. դրա՛ն լսեք»։","6":"Երբ աշակերտները լսեցին, երեսնիվայր ընկան ու շատ վախեցան։","7":"Հիսուսը մոտեցավ, դիպավ նրանց ու ասաց. «Վե՛ր կացեք ու մի՛ վախեցեք»։","8":"Նրանք աչքերը բարձրացրին և Հիսուսից բացի ոչ ոքի չտեսան։","9":"Լեռան վրայից իջնելիս Հիսուսը պատվիրեց նրանց ու ասաց. «Այդ տեսիլքի մասին ոչ ոքի չպատմեք, մինչև որ Մարդու Որդին մեռելներից հարություն չառնի»։","10":"Աշակերտները նրան հարցրին. «Արդ դպիրներն ինչո՞ւ են ասում, թե նախ Եղիան պետք է գա»։","11":"Հիսուսը պատասխանեց նրանց և ասաց. «Նախ Եղիան կգա և ամեն ինչ կվերահաստատի։","12":"Սակայն ես ձեզ ասում եմ, որ Եղիան արդեն եկել է, բայց նրան չճանաչեցին, այլ նրա հետ վարվեցին, ինչպես կամեցան։ Այդպես էլ Մարդու Որդին է նրանց կողմից չարչարվելու»։","13":"Այդ ժամանակ աշակերտները հասկացան, որ Հովհաննես Մկրտչի մասին էր ասում իրենց։","14":"Երբ նրանք ժողովրդի մոտ եկան, Հիսուսին մի մարդ մոտեցավ, ծնկի իջավ և ասաց.","15":"«Տե՛ր, ողորմի՛ր իմ որդուն, որովհետև լուսնոտ է և սաստիկ տանջվում է. հաճախ ընկնում է կրակի կամ ջրի մեջ։","16":"Ես նրան քո աշակերտների մոտ բերեցի, բայց նրան չկարողացան բժշկել»։","17":"Հիսուսը պատասխանեց և ասաց. «Ո՛վ անհավատ ու մոլորյալ սերունդ, մինչև ե՞րբ պետք է ձեզ հետ լինեմ, մինչև ե՞րբ պետք է ձեզ հանդուրժեմ։ Նրան ինձ մոտ՝ այստե՛ղ բերեք»։","18":"Հիսուսը նրան սաստեց, և դևը նրա միջից դուրս ելավ, ու տղան նույն պահին բժշկվեց։","19":"Այդ ժամանակ աշակերտներն առանձին մոտեցան Հիսուսին և ասացին. «Ինչո՞ւ մենք չկարողացանք նրան հանել»։","20":"Հիսուսը նրանց ասաց. «Ձեր թերահավատության պատճառով։ Ճշմարիտ եմ ասում ձեզ. եթե մանանեխի հատիկի չափ հավատ ունենաք և այս սարին ասեք՝ \"Այստեղից այնտե՛ղ փոխադրվիր\", այն կփոխադրվի։ Եվ ձեզ համար անկարելի ոչինչ չի լինի։","21":"Բայց այս դիվային սերունդն այլ կերպ դուրս չի գալիս, եթե ոչ աղոթքով ու ծոմով»։","22":"Երբ նրանք Գալիլեայում շրջում էին, Հիսուսը նրանց ասաց. «Մարդու Որդին մարդկանց ձեռքն է մատնվելու։","23":"Նրան սպանելու են, և երրորդ օրը նա հարություն է առնելու»։ Եվ նրանք շատ տրտմեցին։","24":"Երբ նրանք Կափառնաում եկան, երկդրամյան տուրք հավաքողները մոտեցան Պետրոսին և ասացին. «Ձեր վարդապետը երկդրամյանը չի՞ վճարում»։","25":"Նա ասաց. «Այո՛, վճարում է»։ Երբ նա տուն մտավ, Հիսուսը նրան կանխեց և ասաց. «Քեզ ի՞նչ է թվում, Սիմո՛ն, երկրի թագավորներն ումի՞ց են հարկը կամ տուրքը վերցնում՝ իրենց զավակների՞ց, թե՞ օտարներից»։","26":"Երբ Պետրոսը նրան պատասխանեց՝ օտարներից, Հիսուսը նրան ասաց. «Ուրեմն որդիներն ազատ են։","27":"Բայց որպեսզի նրանց չգայթակղեցնենք, գնա՛ լիճ, կա՛րթ գցիր և դուրս եկած առաջին ձուկը վերցրո՛ւ, բերանը բա՛ց արա և մի սատեր կգտնես։ Վերցրո՛ւ այն և նրա՛նց տուր իմ ու քո տեղը»։"},"18":{"1":"Այդ նույն ժամին աշակերտները մոտեցան Հիսուսին և ասացին. «Ո՞վ է ավելի մեծ երկնքի արքայության մեջ»։","2":"Հիսուսն իր մոտ կանչեց մի երեխայի, նրան աշակերտների մեջտեղում կանգնեցրեց","3":"և ասաց. «Ճշմարիտ եմ ասում ձեզ. եթե դարձի չգաք ու երեխաների նման չլինեք, երկնքի արքայություն չեք մտնի։","4":"Արդ, ով իր անձը խոնարհեցնի, ինչպես այս երեխան է, նա՛ է ավելի մեծը երկնքի արքայության մեջ։","5":"Եվ ով իմ անունով այսպիսի մի երեխայի ընդունի, ի՛նձ ընդունած կլինի։","6":"Իսկ ով ինձ հավատացող այս փոքրերից մեկին գայթակղեցնի, նրա համար ավելի լավ է, որ նրա վզից մի աղացքար կախվի, և նա ծովի հատակը սուզվի։","7":"Վա՜յ աշխարհին գայթակղությունների պատճառով. որովհետև հարկ է, որ գայթակղությունները գան, սակայն վա՛յ այն մարդուն, որի միջոցով գայթակղությունը կգա։","8":"Եթե ձեռքդ կամ ոտքդ քեզ գայթակղեցնում է, կտրի՛ր այն ու դե՛ն գցիր. քեզ համար ավելի լավ է՝ կաղ կամ հաշմանդամ կյանք մտնես, քան երկու ձեռք ու երկու ոտք ունենաս, բայց հավիտենական կրակի մեջ գցվես։","9":"Եվ եթե աչքդ գայթակղեցնում է քեզ, հանի՛ր այն ու դե՛ն նետիր. քեզ համար ավելի լավ է՝ մեկ աչքով կյանք մտնես, քան երկու աչք ունենաս, բայց կրակի գեհենը գցվես։","10":"Զգո՛ւյշ եղեք, որ այս փոքրիկներից որևէ մեկին չանարգեք, որովհետև ասում եմ ձեզ, որ նրանց հրեշտակները երկնքում մշտապես տեսնում են իմ երկնավոր Հոր երեսը։","11":"Որովհետև Մարդու Որդին եկավ կորածին փրկելու։","12":"Ի՞նչ եք կարծում. եթե մի մարդ հարյուր ոչխար ունենա, ու նրանցից մեկը մոլորվի, նա իննսունիննին չի՞ թողնի լեռներում և գնա մոլորվածին որոնելու։","13":"Եվ եթե դրան գտնի, ճշմարիտ եմ ասում ձեզ, դրա համար ավելի կուրախանա, քան այն իննսունիննի, որոնք չեն մոլորվել։","14":"Այսպես էլ ձեր երկնավոր Հայրը չի կամենում, որ այս փոքրիկներից որևէ մեկը կորչի։","15":"Եթե եղբայրդ քո դեմ մեղանչի, գնա հանդիմանի՛ր նրան, երբ դու և նա առանձին լինեք։ Եթե քեզ լսի, քո եղբորը շահած կլինես։","16":"Բայց եթե քեզ չլսի, վերցրո՛ւ քեզ հետ մեկ կամ երկու հոգու ևս, որպեսզի երկու կամ երեք վկաների բերանով ամեն բան հաստատվի (Բ Օր. 19.15)։","17":"Սակայն եթե նրանց էլ չլսի, եկեղեցո՛ւն ասա։ Եթե եկեղեցուն էլ չլսի, թող քեզ համար հեթանոսի ու մաքսավորի պես լինի։","18":"Ճշմարիտ եմ ասում ձեզ. ինչ որ երկրի վրա կապեք, կապված կլինի երկնքում, և ինչ որ երկրի վրա արձակեք, արձակված կլինի նաև երկնքում։","19":"Դարձյալ ասում եմ ձեզ. եթե ձեզանից երկու հոգի մեկ բանի համար երկրի վրա միաբանվեն, ինչ որ խնդրեն, կլինի նրանց իմ Հորից, որ երկնքում է։","20":"Որովհետև որտեղ երկու կամ երեք հոգի իմ անունով հավաքված լինեն, ես այնտեղ՝ նրանց մեջ եմ»։","21":"Այդ ժամանակ Պետրոսը, մոտենալով նրան, ասաց. «Տե՛ր, եթե եղբայրս իմ դեմ մեղանչի, քանի՞ անգամ նրան ներեմ՝ մինչև յո՞թ անգամ»։","22":"Հիսուսը նրան ասաց. «Քեզ չեմ ասում՝ մինչև յոթ անգամ, այլ մինչև յոթանասուն անգամ յոթ։","23":"Դրա համար երկնքի թագավորությունը նման է մի թագավորի, որը ցանկացավ, որ իր ծառաներն իրեն հաշիվ տան։","24":"Երբ սկսեց հաշիվը տեսնել, նրա մոտ բերվեց մեկը, որ պարտք էր տասը հազար քանքար։","25":"Քանի որ պարտքը վերադարձնելու ոչինչ չուներ, նրա տերը հրամայեց վաճառել իրեն, իր կնոջը, որդիներին, ամբողջ ունեցածը և հատուցել։","26":"Այդժամ ծառան ընկավ նրա առաջ, երկրպագում էր նրան և ասում. \"Տե՛ր, համբերատա՛ր եղիր իմ նկատմամբ, և բոլորը կհատուցեմ քեզ\"։","27":"Տերն այդ ծառային գթաց, արձակեց նրան և պարտքը նրան ներեց։","28":"Երբ այդ ծառան դուրս եկավ, գտավ իր ծառայակիցներից մեկին, որն իրեն հարյուր դինար էր պարտք։ Բռնեց նրան և խեղդում էր՝ ասելով. \"Պարտքդ վերադարձրո՛ւ\"։","29":"Այդ ժամանակ ծառայակիցը նրա առաջն ընկավ, աղաչում էր նրան և ասում. \"Համբերատա՛ր եղիր իմ նկատմամբ, և բոլորը կհատուցեմ քեզ\"։","30":"Բայց նա չկամեցավ, այլ գնաց և նրան բանտ գցեց, մինչև պարտքը հատուցեր։","31":"Երբ նրա ծառայակիցները տեսան պատահածը, շատ տրտմեցին և եկան, ամեն ինչ հայտնեցին իրենց տիրոջը։","32":"Այդ ժամանակ տերը նրան իր մոտ կանչեց և ասաց. \"Չա՛ր ծառա, ես ամբողջ պարտքդ քեզ ներեցի, որովհետև դու ինձ աղաչեցիր։","33":"Պետք չէ՞ր, որ դու էլ քո ծառայակցին ողորմեիր, ինչպես ես քեզ ողորմեցի\"։","34":"Եվ տերը բարկանալով՝ նրան հանձնեց դահիճներին, մինչև հատուցեր ամբողջ պարտքը։","35":"Այդպես էլ իմ երկնավոր Հայրը կանի ձեզ, եթե ձեզանից յուրաքանչյուրն իր եղբոր հանցանքները սրտանց չների»։"},"19":{"1":"Երբ Հիսուսն այս խոսքերն ավարտեց, Գալիլեայից հեռացավ և եկավ Հրեաստանի սահմանները՝ Հորդանանի մյուս կողմը։","2":"Նրա հետևից ժողովրդի մեծ բազմություն էր գնում, և նրանց այնտեղ բժշկում էր։","3":"Փարիսեցիները նրա մոտ եկան և նրան փորձելու համար ասում էին. «Արդյոք թույլատրվո՞ւմ է, որ մարդն առանց որևէ պատճառի արձակի իր կնոջը»։","4":"Հիսուսը պատասխանեց ու ասաց նրանց. «Չե՞ք կարդացել, որ արարիչը սկզբից արու և էգ ստեղծեց նրանց (Ծնն. 1.27, 5.2)","5":"ու ասաց. \"Դրա համար տղամարդը պիտի թողնի իր հորն ու մորը և միանա իր կնոջը, և երկուսը մեկ մարմին պիտի լինեն\" (Ծնն. 2.24),","6":"որպեսզի այլևս չլինեն երկու, այլ մեկ մարմին։ Արդ, ինչ որ Աստված միացրեց, մարդը թող չբաժանի»։","7":"Նրան ասացին. «Ուրեմն ինչո՞ւ Մովսեսը մեզ պատվիրեց արձակման թուղթ տալ ու արձակել նրան» (Բ Օր. 24.1-4, Մտթ. 5.31)։","8":"Նրանց ասաց. «Մովսեսը ձեր խստասրտության պատճառով ձեզ թույլատրեց ձեր կանանց արձակել, բայց սկզբում այդպես չի եղել։","9":"Բայց ասում եմ ձեզ. ով իր կնոջն արձակի ոչ պոռնկության պատճառով և ուրիշի հետ ամուսնանա, շնություն արած կլինի. շնություն է անում նաև նա, ով արձակվածի հետ է ամուսնանում»։","10":"Աշակերտներն ասացին նրան. «Եթե ամուսնու հարաբերությունը կնոջ հետ այդպիսին է, ավելի լավ է չամուսնանալ»։","11":"Իսկ Հիսուսն ասաց նրանց. «Ոչ բոլորն են դրան ընդունակ, այլ նրանք, ում տրված է։","12":"Որովհետև կան ներքինիներ, որոնք մոր որովայնից են այդպես ծնվել, կան նաև ներքինիներ, որոնք մարդկանց կողմից են ներքինի դարձվել, ներքինիներ էլ կան, որոնք երկնքի արքայության համար են իրենք իրենց ներքինի դարձրել։ Ով կարող է այս ճանապարհով ընթանալ, թող ընթանա»։","13":"Այդ ժամանակ Հիսուսի մոտ երեխաների բերեցին, որպեսզի ձեռքը դնի նրանց վրա և աղոթի, սակայն աշակերտները հանդիմանում էին նրանց։","14":"Բայց Հիսուսն ասաց. «Թողե՛ք այդ երեխաներին և մի՛ արգելեք նրանց ինձ մոտ գալ, որովհետև երկնքի արքայությունն այդպիսիներինն է»։","15":"Եվ ձեռքը դրեց նրանց վրա ու այնտեղից գնաց։","16":"Ահա մեկը Հիսուսի մոտ եկավ ու ասաց. «Բարի՛ վարդապետ, ի՞նչ բարի գործ անեմ, որ հավիտենական կյանքն ունենամ»։","17":"Նա ասաց նրան. «Ինչո՞ւ ես ինձ բարու մասին հարցնում. բարին մեկն է։ Իսկ թե ուզում ես հավիտենական կյանք մտնել, պատվիրաննե՛րը պահիր»։","18":"Նրան ասաց. «Որո՞նք»։ Հիսուսն ասաց. «Մի՛ սպանիր, մի՛ շնանա, մի՛ գողանա, սուտ մի՛ վկայիր,","19":"պատվի՛ր քո հորն ու մորը և սիրի՛ր քո ընկերոջը, ինչպես ինքդ քեզ» (Ելք 20.13-16, 12, Բ Օր. 5.17-20, 16, Ղևտ. 19.18)։","20":"Երիտասարդը նրան ասաց. «Այդ ամենն իմ մանկությունից ի վեր պահել եմ, էլ ի՞նչ է ինձ պակասում»։","21":"Հիսուսը նրան ասաց. «Եթե ուզում ես կատարյալ լինել, գնա վաճառի՛ր ունեցվածքդ ու տո՛ւր աղքատներին և երկնքում գանձ կունենաս. ու եկ ի՛նձ հետևիր»։","22":"Երբ երիտասարդն այս խոսքը լսեց, տրտմած հեռացավ, որովհետև մեծ հարստություն ուներ։","23":"Հիսուսն աշակերտներին ասաց. «Ճշմարիտ եմ ասում ձեզ, որ հարուստը դժվարությամբ է երկնքի արքայություն մտնելու։","24":"Բայց դարձյալ ասում եմ ձեզ. ուղտն ասեղի ծակով ավելի հեշտ կանցնի, քան հարուստը Աստծու արքայություն կմտնի»։","25":"Երբ աշակերտները լսեցին, շատ զարմացան ու ասացին. «Հապա ո՞վ կարող է փրկվել»։","26":"Հիսուսը նայեց նրանց և ասաց. «Մարդկանց համար դա անհնար է, բայց Աստծու համար ամեն բան հնարավոր է»։","27":"Այդ ժամանակ Պետրոսն ասաց Հիսուսին. «Ահա մենք ամեն ինչ թողեցինք ու եկանք քո հետևից. հիմա մեզ ի՞նչ կլինի»։","28":"Հիսուսը նրանց ասաց. «Ճշմարիտ եմ ասում ձեզ, որ դուք՝ իմ հետևից եկողներդ, երբ Մարդու Որդին երկրորդ գալստյանն իր փառքի աթոռին նստի, դուք տասներկու աթոռների վրա կնստեք՝ Իսրայելի տասներկու ցեղերին դատելու։","29":"Ամեն ոք, ով իմ անվան համար թողել է տունը կամ եղբայրներին, կամ քույրերին, կամ հորը, կամ մորը, կամ կնոջը, կամ զավակներին, կամ արտերը, հարյուրապատիկը կստանա ու հավիտենական կյանքը կժառանգի։","30":"Շատ առաջիններ վերջիններ կլինեն, իսկ վերջինները՝ առաջիններ»։"},"20":{"1":"«Երկնքի արքայությունը նման է մի տանուտեր մարդու, որ վաղ առավոտյան դուրս եկավ իր այգու համար մշակներ վարձելու։","2":"Եվ մշակների հետ օրավարձը մեկ դինար համաձայնության գալուց հետո նրանց իր այգին ուղարկեց։","3":"Երրորդ ժամին մոտ դուրս ելնելով՝ տեսավ ուրիշների, որ հրապարակում անգործ կանգնել էին։","4":"Նրանց էլ ասաց. \"Դո՛ւք էլ այգի գնացեք, և ինչ որ արժան է, ձեզ կտամ\"։","5":"Նրանք էլ գնացին։ Ապա վեցերորդ և իններորդ ժամերին դարձյալ դուրս ելնելով՝ նույն բանն արեց։","6":"Տասնմեկերորդ ժամին մոտ ևս դուրս ելնելով՝ գտավ ուրիշների՝ անգործ կանգնած, և նրանց հարցրեց. \"Ինչո՞ւ եք ամբողջ օրն անգործ կանգնել այստեղ\"։","7":"Նրան պատասխանեցին. \"Որովհետև ոչ ոք մեզ չվարձեց\"։ Նրանց ասաց. \"Դո՛ւք էլ այգի գնացեք, և ինչ որ արժան է, կստանաք\"։","8":"Երբ երեկո եղավ, այգու տերն իր գործավարին ասաց. \"Կանչի՛ր մշակներին ու տո՛ւր նրանց վարձը՝ վերջիններից սկսած մինչև առաջինները\"։","9":"Ովքեր տասնմեկերորդ ժամին էին վարձվել, եկան և մեկական դինար ստացան։","10":"Եկան նաև առաջին ժամին վարձվածները և կարծում էին, թե ավելին կստանան, սակայն նրանք էլ մեկական դինար ստացան։","11":"Բայց երբ ստացան, տանտիրոջը տրտնջացին","12":"ու ասացին. \"Այդ վերջինները մեկ ժամ աշխատեցին, իսկ դու նրանց հավասար դարձրեցիր մեզ, որ օրվա ծանրությունն ու շոգը տարանք\"։","13":"Նա նրանցից մեկին պատասխանեց ու ասաց. \"Ընկե՛ր, ես քեզ չեմ զրկում. չէ՞ որ դու ինձ հետ մեկ դինարով համաձայնվեցիր։","14":"Վերցրո՛ւ քոնը ու գնա՛։ Ես ուզում եմ այս վերջինին ևս վճարել այնքան, որքան քեզ։","15":"Մի՞թե ես իրավունք չունեմ ուզածիս պես վարվելու ունեցածիս հետ. թե՞ գուցե նախանձում ես, որ ես բարի եմ\"։","16":"Այսպես էլ վերջինները կլինեն առաջիններ, իսկ առաջինները՝ վերջիններ»։","17":"Երբ Հիսուսը Երուսաղեմ էր բարձրանում, տասներկու աշակերտներին առանձնացրեց և ճանապարհին նրանց ասաց.","18":"«Ահա Երուսաղեմ ենք բարձրանում, և Մարդու Որդին մատնվելու է քահանայապետներին ու դպիրներին։ Նրան մահվան են դատապարտելու","19":"և հեթանոսներին են մատնելու. նա ծաղրվելու է, գանահարվելու է և խաչն է հանվելու, սակայն երրորդ օրը հարություն է առնելու»։","20":"Այդ ժամանակ Հիսուսին մոտեցավ Զեբեդեոսի որդիների մայրն իր որդիների հետ, երկրպագեց ու նրանից մի բան խնդրեց։","21":"Հիսուսը նրան հարցրեց. «Ի՞նչ ես ուզում»։ Կինը նրան ասաց. «Ասա՛, որ իմ այս երկու որդիները քո արքայության մեջ նստեն. մեկը՝ քո աջ կողմում, իսկ մյուսը՝ ձախ կողմում»։","22":"Հիսուսը պատասխանեց ու ասաց. «Չգիտեք, թե ի՛նչ եք խնդրում։ Կարո՞ղ եք խմել այն բաժակը, որը ես եմ խմելու, կամ մկրտվել այն մկրտությամբ, որով ես եմ մկրտվելու»։ Նրան ասացին. «Կարող ենք»։","23":"Հիսուսն ասաց նրանց. «Իմ բաժակը խմելու եք և այն մկրտությամբ, որով ես պիտի մկրտվեմ, մկրտվելու եք, բայց իմ աջ ու ձախ կողմերում նստեցնելը ե՛ս չեմ տալիս. դա կտրվի նրանց, որոնց համար պատրաստված է իմ Հոր կողմից»։","24":"Երբ մյուս տասը լսեցին, զայրացան երկու եղբայրների վրա։","25":"Հիսուսը նրանց իր մոտ կանչեց և ասաց. «Գիտեք, որ առաջնորդները տիրում են ազգերին, և իշխանավորները իշխանություն են բանեցնում նրանց վրա։","26":"Բայց ձեր մեջ այդպես չպետք է լինի, այլ ձեզանից ով ցանկանա մեծ լինել, ձեր ծառան պետք է լինի,","27":"և ձեզանից ով ցանկանա առաջինը լինել, ձեր ծառան պետք է լինի,","28":"ինչպես որ Մարդու Որդին չեկավ, որ իրեն ծառայեն, այլ որպեսզի ինքը ծառայի և շատերի փոխարեն իր կյանքը որպես փրկագին տա»։","29":"Երբ նրանք Երիքովից դուրս էին գալիս, նրանց ժողովրդի մեծ բազմություն հետևեց։","30":"Ահա ճանապարհին երկու կույրեր էին նստած։ Երբ լսեցին, որ Հիսուսն անցնում է, աղաղակեցին ու ասացին. «Ողորմի՛ր մեզ, Տե՛ր, Դավթի՛ Որդի»։","31":"Իսկ մարդիկ նրանց սաստում էին, որ լռեն. բայց նրանք ավելի բարձր էին աղաղակում ու ասում. «Ողորմի՛ր մեզ, Տե՛ր, Դավթի՛ Որդի»։","32":"Հիսուսը կանգնեց, նրանց կանչեց ու ասաց. «Ի՞նչ եք ուզում, որ անեմ ձեզ համար»։","33":"Նրան ասացին. «Տե՛ր, թող մեր աչքերը բացվեն»։","34":"Հիսուսը գթաց, նրանց աչքերին դիպավ, և նրանց տեսողությունն իսկույն վերականգնվեց, ու նրանք գնացին նրա հետևից։"},"21":{"1":"Երբ մոտեցան Երուսաղեմին ու եկան Բեթփագե՝ Ձիթենյաց լեռան մոտ, այդ ժամանակ Հիսուսը երկու աշակերտի ուղարկեց","2":"և նրանց ասաց. «Գնացե՛ք ձեր դիմացի գյուղը և այնտեղ անմիջապես կգտնեք մի կապած էշ, քուռակն էլ հետը։ Արձակե՛ք, ինձ մո՛տ բերեք։","3":"Եթե որևէ մեկը ձեզ ինչ-որ բան ասի, ասե՛ք, որ դրանք պետք են Տիրոջը, և նա իսկույն դրանք կուղարկի»։","4":"Բայց այս ամենը եղավ, որպեսզի իրականանար մարգարեի միջոցով ասված խոսքը.","5":"«Սիոնի դստերն ասե՛ք. \"Ահա քեզ մոտ է գալիս քո թագավորը՝ հեզ, էշին ու քուռակին հեծած\" (Զաք. 9.9)»։","6":"Աշակերտները գնացին ու արեցին այնպես, ինչպես Հիսուսը նրանց պատվիրեց։","7":"Էշն ու քուռակը բերեցին, իրենց հագուստները դրանց վրա գցեցին, և Հիսուսը դրանց վրա նստեց։","8":"Ժողովրդի միջից շատերն իրենց հագուստները փռում էին ճանապարհին, ուրիշներն էլ ծառերից ճյուղեր էին կտրում ու ճանապարհին փռում։","9":"Եվ առջևից ու հետևից գնացող բազմությունը բացականչում էր ու ասում. «Օվսաննա՜ Դավթի Որդուն (եբր. Սաղ. 118.25), օրհնյա՜լ է Տիրոջ անունով եկողը (Սաղ. 118.26). օվսաննա՜ Բարձրյալին»։","10":"Երբ Հիսուսը Երուսաղեմ մտավ, ամբողջ քաղաքը ցնցվեց։ Հարցնում էին. «Ո՞վ է սա»։","11":"Եվ ժողովրդի բազմությունն ասում էր. «Սա Հիսուս մարգարեն է՝ Գալիլեայի Նազարեթ քաղաքից»։","12":"Հիսուսը մտավ Աստծու տաճարը և վռնդեց տաճարից բոլոր առք ու վաճառք անողներին, ավերեց լումայափոխների սեղանները և աղավնեվաճառների աթոռները։","13":"Եվ ասաց նրանց. «Գրված է. \"Իմ տունն աղոթքի տուն պիտի կոչվի\" (Ես. 56.7բ), իսկ դուք այն ավազակների որջ եք դարձրել»։","14":"Տաճարում նրան մոտեցան կույրեր ու կաղեր, և նա բժշկեց նրանց։","15":"Երբ քահանայապետներն ու դպիրները տեսան նրա կատարած հրաշքները և երեխաներին, որոնք տաճարում բացականչում էին. «Օվսաննա՜ Դավթի Որդուն», բարկացան։","16":"Եվ նրան ասացին. «Լսո՞ւմ ես՝ դրանք ի՛նչ են ասում»։ Հիսուսը նրանց ասաց. «Այո՛, դուք երբևէ չե՞ք կարդացել. \"Մանուկների ու կաթնակերների բերանով օրհնություն կատարեցիր\" (Սաղ. 8.2)»։","17":"Եվ թողնելով նրանց՝ գնաց քաղաքից դուրս՝ Բեթանիա, և գիշերն այնտեղ մնաց։","18":"Առավոտյան, երբ Հիսուսը քաղաք էր վերադառնում, քաղց զգաց։","19":"Ճանապարհին մի թզենի տեսնելով՝ մոտեցավ, բայց վրան ոչինչ չգտավ, բացի տերևից։ Եվ թզենուն ասաց. «Թող քեզանից հավիտյան պտուղ չլինի», ու թզենին իսկույն չորացավ։","20":"Երբ աշակերտները տեսան, զարմացան և ասացին. «Թզենին ինչպե՞ս իսկույն չորացավ»։","21":"Հիսուսը պատասխանեց ու նրանց ասաց. «Ճշմարիտ եմ ասում ձեզ. եթե հավատ ունենաք ու չերկմտեք, ոչ միայն թզենու հետ պատահածը կանեք, այլև եթե այդ լեռանն ասեք՝ \"Ե՛լ և ծո՛վն ընկիր\", կկատարվի։","22":"Եվ այն ամենը, ինչ աղոթքի մեջ հավատքով խնդրեք, կստանաք»։","23":"Երբ Հիսուսը տաճար եկավ և ուսուցանում էր, նրան մոտեցան քահանայապետներն ու ժողովրդի ծերերը և ասացին. «Ի՞նչ իշխանությամբ ես այդ բաներն անում, և ո՞վ տվեց քեզ այդ իշխանությունը»։","24":"Հիսուսը պատասխանեց նրանց. «Ես էլ ձե՛զ մի բան հարցնեմ. եթե ինձ ասեք, ես էլ ձեզ կասեմ, թե ի՛նչ իշխանությամբ եմ այս բաներն անում։","25":"Հովհաննեսի մկրտությունը որտեղի՞ց էր՝ երկնքի՞ց, թե՞ մարդկանցից»։ Եվ նրանք իրար մեջ խորհուրդ էին անում և ասում. «Եթե ասենք՝ երկնքից, մեզ կասի. \"Հապա ինչո՞ւ չհավատացիք նրան\",","26":"իսկ եթե ասենք՝ մարդկանցից, ժողովրդից ենք վախենում, որովհետև բոլորը Հովհաննեսին մարգարե են համարում»։","27":"Հիսուսին պատասխանեցին ու ասացին՝ չգիտենք։ Նա էլ ասաց նրանց. «Ես էլ ձե՛զ չեմ ասի, թե ի՛նչ իշխանությամբ եմ այս բաներն անում։","28":"Բայց դուք ի՞նչ եք կարծում։ Մի մարդ երկու որդի ուներ։ Նա եկավ և առաջինին ասաց. \"Որդի՛, այսօր գնա՛, իմ այգում աշխատի՛ր\"։","29":"Իսկ նա պատասխանեց ու ասաց. \"Չեմ ուզում\", բայց հետո զղջաց ու գնաց։","30":"Գնաց մյուսի մոտ և նույնն ասաց։ Նա էլ պատասխանեց ու ասաց. \"Կգնա՛մ, տե՛ր\", ու չգնաց։","31":"Այդ երկուսից ո՞վ հոր կամքը կատարեց»։ Նրան ասացին՝ առաջինը։ Հիսուսը նրանց ասաց. «Ճշմարիտ եմ ասում ձեզ, որ մաքսավորներն ու պոռնիկները ձեզանից առաջ կմտնեն Աստծու արքայություն։","32":"Որովհետև Հովհաննեսը ձեզ մոտ արդարության ճանապարհով եկավ, իսկ դուք նրան չհավատացիք, բայց մաքսավորներն ու պոռնիկները նրան հավատացին։ Դուք դա տեսաք, բայց հետո էլ չզղջացիք ու նրան չհավատացիք։","33":"Մի ուրի՛շ առակ լսեք։ Մի տանուտեր մարդ կար, որն այգի տնկեց, ցանկապատեց այն, մեջը հնձան փորեց ու աշտարակ շինեց, ապա այն տվեց մշակներին և օտար երկիր գնաց։","34":"Երբ բերքի ժամանակը մոտեցավ, իր ծառաներին մշակների մոտ ուղարկեց՝ բերքից իր բաժինը վերցնելու։","35":"Մշակները նրա ծառաներին բռնեցին, մեկին ծեծեցին, մեկին սպանեցին, մեկին էլ քարկոծեցին։","36":"Դարձյալ ուրիշ՝ նախկիններից շատ ծառաների ուղարկեց. սրանց էլ նույնն արեցին։","37":"Վերջապես նրանց մոտ իր որդուն ուղարկեց՝ ասելով. \"Իմ որդուց կամաչեն\"։","38":"Բայց մշակները, որդուն տեսնելով, իրար մեջ ասացին. \"Սա է ժառանգը. եկեք սրան սպանենք և սրա ժառանգությանը տիրանանք\"։","39":"Եվ բռնեցին նրան, այգուց դուրս հանեցին ու սպանեցին։","40":"Արդ, երբ այգու տերը գա, այն մշակներին ի՞նչ կանի»։","41":"Նրան ասացին. «Չարերին դաժանորեն կորստյան կմատնի, իսկ այգին ուրիշ մշակների կտա, որոնք բերքը ժամանակին իրեն կտան»։","42":"Հիսուսը նրանց ասաց. «Դուք Սուրբ Գրքում երբեք չե՞ք կարդացել. \"Այն քարը, որ շինարարները մերժեցին, անկյունաքար դարձավ. սա Տիրոջ կողմից եղավ, և մեր աչքին զարմանալի է\" (Սաղ. 118.22-23)։","43":"Դրա համար ասում եմ ձեզ, որ Աստծու արքայությունը ձեզանից կվերցվի և կտրվի մի ազգի, որն այն պտղաբեր կդարձնի։","44":"Ով այս քարի վրա ընկնի, ջարդուփշուր կլինի, իսկ ում վրա այն ընկնի, նրան կճզմի»։","45":"Երբ քահանայապետներն ու փարիսեցիները նրա առակները լսեցին, հասկացան, որ իրենց մասին է ասում։","46":"Եվ ուզում էին նրան բռնել, բայց ժողովրդից վախեցան, որովհետև նրան մարգարե էին համարում։"},"22":{"1":"Հիսուսը նրանց հետ դարձյալ առակներով խոսեց և ասաց.","2":"«Երկնքի արքայությունը նման է թագավոր մարդու, որն իր որդու համար հարսանիք արեց։","3":"Նա իր ծառաներին ուղարկեց հրավիրյալներին հարսանիքի կանչելու, բայց նրանք չկամեցան գալ։","4":"Դարձյալ ուրիշ ծառաների ուղարկեց և ասաց. \"Հրավիրյալներին ասե՛ք. “Ահա պատրաստեցի իմ ճաշկերույթը, իմ ցլիկներն ու պարարտ անասունները մորթված են, ամեն ինչ պատրաստ է, եկե՛ք հարսանիքի”\"։","5":"Իսկ նրանք անտեսելով հեռացան. մեկը՝ իր արտը, մյուսը՝ իր առևտրին։","6":"Իսկ մնացածները նրա ծառաներին բռնեցին, վիրավորեցին ու սպանեցին։","7":"Երբ թագավորը լսեց, բարկացավ և իր զորքն ուղարկեց, կոտորեց մարդասպաններին և այրեց նրանց քաղաքը։","8":"Այդ ժամանակ նա իր ծառաներին ասաց. \"Հարսանիքը պատրաստ է, բայց հրավիրվածներն արժանի չէին։","9":"Արդ գնացե՛ք ճանապարհների խաչմերուկներ և ում գտնեք, հարսանիքի՛ հրավիրեք\"։","10":"Եվ ծառաները ելան դեպի ճանապարհները և ում գտան, բոլորին հավաքեցին՝ և՛ չարերին, և՛ բարիներին։ Եվ հարսանիքը լցվեց հրավիրյալներով։","11":"Երբ թագավորը ներս մտավ հյուրերին տեսնելու, այնտեղ մի մարդու նկատեց, որը հարսանքավորի զգեստ չէր հագել։","12":"Նրան ասաց. \"Ընկե՛ր, առանց հարսանքավորի զգեստ ունենալու ինչպե՞ս այստեղ մտար\"։ Նա պապանձվեց։","13":"Այդ ժամանակ թագավորը ծառաներին ասաց. \"Կապե՛ք դրա ոտքերն ու ձեռքերը, վերցրե՛ք դրան և գցե՛ք դուրս՝ խավարի մեջ. այնտեղ կլինի լաց ու ատամների կրճտոց։","14":"Որովհետև կանչվածները շատ են, իսկ ընտրյալները՝ քիչ\"»։","15":"Այդ ժամանակ փարիսեցիները գնացին և խորհրդակցում էին, թե ինչպե՛ս Հիսուսին խոսքով ծուղակը գցեն։","16":"Եվ հերովդեսականների հետ նրա մոտ ուղարկեցին իրենց աշակերտներին ու ասացին. «Վարդապե՛տ, գիտենք, որ ճշմարիտ ես և Աստծու ճանապարհը ճշմարտությամբ ես ուսուցանում և ոչ մեկից չես վախենում, որովհետև երեսպաշտություն չես անում։","17":"Արդ ասա՛ մեզ, դու ի՞նչ ես կարծում, օրինավո՞ր է կայսրին հարկ տալ, թե՞ ոչ»։","18":"Հիսուսը հասկացավ նրանց խորամանկությունը և ասաց. «Ինչո՞ւ եք ինձ փորձում, կեղծավորնե՛ր։","19":"Ցո՛ւյց տվեք ինձ հարկի դինարը»։ Նրանք Հիսուսին մի դինար բերեցին։","20":"Եվ նրանց ասաց. «Ո՞ւմն են այս պատկերը և գիրը»։ Նրան ասացին՝ կայսրինը։","21":"Այդ ժամանակ ասաց. «Ուրեմն կայսրինը տվե՛ք կայսրին, իսկ Աստծունը՝ Աստծուն»։","22":"Երբ լսեցին, զարմացան, թողեցին նրան ու գնացին։","23":"Այդ օրը Հիսուսի մոտ եկան սադուկեցիները, որոնք ասում էին, թե հարություն չկա։ Հարց տվեցին նրան","24":"ու ասացին. «Վարդապե՛տ, Մովսեսն ասաց. \"Եթե մի մարդ անզավակ մեռնի, նրա եղբայրը թող ամուսնանա նրա կնոջ հետ ու իր եղբոր համար զավակ բերի\" (Բ Օր. 25.5)։","25":"Մեզ մոտ յոթ եղբայրներ կային։ Առաջինն ամուսնացավ ու մեռավ և որովհետև զավակ չուներ, իր կնոջը թողեց իր եղբորը։","26":"Նույն կերպ էլ երկրորդ եղբայրը, երրորդը..., մինչև յոթերորդը։","27":"Բոլորից հետո նաև կինը մեռավ։","28":"Ուրեմն հարության ժամանակ նա յոթից ո՞ր մեկի կինը կլինի, որովհետև բոլորն էլ նրան կնության առան»։","29":"Հիսուսը պատասխանեց ու նրանց ասաց. «Մոլորության մեջ եք. ո՛չ Սուրբ Գիրքն եք հասկանում, ո՛չ էլ Աստծու զորությունը։","30":"Որովհետև հարության ժամանակ ո՛չ կին են առնելու, ո՛չ էլ ամուսին, այլ կլինեն ինչպես Աստծու հրեշտակները երկնքում։","31":"Իսկ մեռելների հարության մասին չե՞ք կարդացել Աստծու կողմից ձեզ ասվածը.","32":"\"Ես եմ Աբրահամի Աստվածը, Իսահակի Աստվածը և Հակոբի Աստվածը\" (Ելք 3.6)։ Աստված մեռածների՛ Աստվածը չէ, այլ ողջերի»։","33":"Եվ ժողովուրդը լսելով՝ զարմանում էր նրա ուսուցման վրա։","34":"Երբ փարիսեցիները լսեցին, որ Հիսուսը պապանձեցրեց սադուկեցիներին, իրար մոտ հավաքվեցին։","35":"Եվ նրանցից մեկը, որ օրենսգետ էր, նրան փորձելու համար հարցրեց ու ասաց.","36":"«Վարդապե՛տ, օրենքի մեջ ո՞րն է ամենամեծ պատվիրանը»։","37":"Հիսուսը նրան ասաց. «\"Սիրի՛ր քո Տեր Աստծուն քո ամբողջ սրտով, քո ամբողջ հոգով, քո ամբողջ մտքով\" (Բ Օր. 6.5)։","38":"Սա է առաջին ու ամենամեծ պատվիրանը։","39":"Երկրորդը նման է սրան. \"Սիրի՛ր քո ընկերոջը, ինչպես ինքդ քեզ\" (Ղևտ. 19.18, Մտթ. 5.43)։","40":"Այս երկու պատվիրաններից են կախված ամբողջ օրենքն ու մարգարեները»։","41":"Երբ փարիսեցիները հավաքված էին, Հիսուսը նրանց հարցրեց ու ասաց.","42":"«Ի՞նչ եք կարծում Քրիստոսի մասին. ո՞ւմ որդին է»։ Նրան պատասխանեցին՝ Դավթի։","43":"Նրանց ասաց. «Հապա ինչպե՞ս է, որ Դավիթը Հոգով նրան \"Տեր\" է կոչում՝ ասելով.","44":"\"Տերն իմ Տիրոջն ասաց. Նստի՛ր իմ աջ կողմում, մինչև քո թշնամիներին իբրև պատվանդան դնեմ ոտքերիդ\" (Սաղ. 110.1)։","45":"Արդ, եթե Դավիթը նրան \"Տեր\" է կոչում, ինչպե՞ս է Քրիստոսը նրա որդին»։","46":"Ոչ ոք չէր կարողանում նրան պատասխանել։ Ոչ էլ որևէ մեկը այդ օրվանից համարձակվեց նրան մի բան հարցնել։"},"23":{"1":"Այդ ժամանակ Հիսուսը խոսեց ժողովրդի ու իր աշակերտների հետ և ասաց.","2":"«Մովսեսի աթոռի վրա նստեցին դպիրներն ու փարիսեցիները։","3":"Արդ, այն ամենը, ինչ ձեզ ասեն, որ պահեք, պահե՛ք ու արե՛ք, բայց նրանց գործերի պե՛ս մի արեք, որովհետև ասում են, բայց չեն անում։","4":"Ծանր ու դժվարակիր բեռներ են կապում և մարդկանց ուսերին դնում, բայց իրենց մատով անգամ չեն ուզում շարժել դրանք։","5":"Իրենց բոլոր գործերը մարդկանց ցույց տալու համար են կատարում. իրենց գրապանակներն են լայնացնում և իրենց հագուստների քղանցքները երկարացնում։","6":"Սիրում են առաջին տեղերը ընթրիքների ժամանակ, ժողովարաններում՝ առաջին աթոռները,","7":"հրապարակներում՝ բարևները և մարդկանց կողմից \"Ռա՛բբի, Ռա՛բբի\" կոչվելը։","8":"Բայց դուք թույլ մի՛ տվեք, որ ձեզ \"Ռաբբի\" կոչեն, որովհետև ձեր ուսուցիչը մեկն է՝ Քրիստոսը, իսկ դուք բոլորդ եղբայրներ եք։","9":"Եվ երկրի վրա ոչ մեկին ձեզ \"Հայր\" մի՛ կոչեք, որովհետև ձեր Հայրը մեկն է՝ նա, որ երկնքում է։","10":"Ոչ էլ \"ուսուցիչներ\" կոչվեք, որովհետև ձեր Ուսուցիչը մեկն է՝ Քրիստոսը։","11":"Եվ ձեզանից ամենամեծը թող ձեր սպասավորը լինի։","12":"Ով իր անձը բարձրացնի, կխոնարհեցվի, և ով իր անձը խոնարհեցնի, կբարձրացվի։","13":"Բայց վա՛յ ձեզ՝ կեղծավորներիդ՝ դպիրներիդ և փարիսեցիներիդ, որ երկնքի արքայությունը փակում եք մարդկանց առաջ. դուք չեք մտնում և փափագողներին էլ թույլ չեք տալիս մտնել։","14":"Վա՛յ ձեզ՝ կեղծավորներիդ՝ դպիրներիդ և փարիսեցիներիդ, որ որբևայրիների ունեցածն եք ուտում և ցուցադրաբար երկար աղոթում. դրա համար խստորեն եք պատժվելու։","15":"Վա՛յ ձեզ՝ կեղծավորներիդ՝ դպիրներիդ և փարիսեցիներիդ, որ ծովով ու ցամաքով շրջում եք, որպեսզի մեկին նորահավատ դարձնեք, ու երբ ստացվում է, նրան ձեզանից կրկնապատիկ ավելի գեհենի որդի եք դարձնում։","16":"Վա՛յ ձեզ, կո՛ւյր առաջնորդներ, որ ասում եք, թե ով երդվում է տաճարով, հոգ չէ, բայց ով տաճարի ոսկով է երդվում, պարտական է։","17":"Անմիտնե՛ր ու կույրե՛ր, ի՞նչն է ավելի մեծ՝ ոսկի՞ն, թե՞ տաճարը, որ սրբագործում է ոսկին։","18":"Նաև ասում եք՝ ով երդվում է զոհասեղանով, հոգ չէ, բայց ով երդվում է ընծայով, որ զոհասեղանի վրա է, պարտական է։","19":"Կույրե՛ր, ի՞նչն է ավելի մեծ՝ ընծա՞ն, թե՞ զոհասեղանը, որ սրբագործում է ընծան։","20":"Արդ, ով երդվում է զոհասեղանով, երդվում է նրանով և այն բոլոր բաներով, որ նրա վրա են։","21":"Տաճարով երդվողը երդվում է նրանով և նրա մեջ բնակվողով։","22":"Երկնքով երդվողը երդվում է Աստծու աթոռով և նրա վրա նստողով։","23":"Վա՛յ ձեզ՝ կեղծավորներիդ՝ դպիրներիդ և փարիսեցիներիդ, որ անանուխի, սամիթի ու չամանի տասանորդը տալիս եք, բայց չեք պահում օրենքի ամենից ծանրակշիռ կետերը՝ արդարությունը, ողորմությունն ու հավատը. դրանք պետք էր կատարել, մյուսներն էլ՝ պահել։","24":"Կո՛ւյր առաջնորդներ, որ մժեղը քամում եք, բայց ուղտը կուլ եք տալիս։","25":"Վա՛յ ձեզ՝ կեղծավորներիդ՝ դպիրներիդ և փարիսեցիներիդ, որ մաքրում եք բաժակի ու ափսեի դրսի կողմը, բայց ներսից լի են հափշտակությամբ ու անժուժկալությամբ։","26":"Կո՛ւյր փարիսեցի, նախ բաժակի ու ափսեի նե՛րսը մաքրիր, որպեսզի դրսի կողմն էլ մաքուր լինի։","27":"Վա՛յ ձեզ՝ կեղծավորներիդ՝ դպիրներիդ և փարիսեցիներիդ, որ նման եք ծեփած գերեզմանների, որոնք արտաքուստ գեղեցիկ են երևում, բայց ներսից լի են մեռելների ոսկորներով ու ամեն տեսակ պղծությամբ։","28":"Դուք նույնպես արտաքուստ արդար եք երևում մարդկանց, բայց ներքուստ լի եք կեղծավորությամբ ու անօրենությամբ։","29":"Վա՛յ ձեզ՝ կեղծավորներիդ՝ դպիրներիդ և փարիսեցիներիդ, որ շինում եք մարգարեների գերեզմաններն ու արդարների շիրիմները զարդարում։","30":"Եվ ասում եք. \"Եթե մենք մեր հայրերի ժամանակ լինեինք, նրանց հետ մարգարեների սպանությանը մասնակից չէինք լինի\"։","31":"Ուրեմն ինքներդ ձեր մասին վկայում եք, որ որդիներն եք մարգարեներին սպանողների։","32":"Արդ դուք էլ լրացրե՛ք ձեր հայրերի բաց թողածը։","33":"Օձե՛ր, իժերի՛ ծնունդներ, ինչպե՞ս եք գեհենի դատաստանից փախչելու։","34":"Դրա համար ահա ես ձեզ մոտ եմ ուղարկելու մարգարեների, իմաստունների ու դպիրների. նրանցից ոմանց սպանելու եք ու խաչը հանելու, ոմանց ձեր ժողովարաններում ծեծելու եք ու քաղաքից քաղաք հալածելու։","35":"Այդպես ձեզ վրա է ընկնելու երկրի վրա թափված ամեն արդար արյան պատասխանատվությունը՝ արդար Աբելի արյունից մինչև Բարաքիայի որդի Զաքարիայի արյունը, որին տաճարի ու զոհասեղանի միջև սպանեցիք։","36":"Ճշմարիտ եմ ասում ձեզ. այս ամենը գալու է այս սերնդի վրա։","37":"Երուսաղե՜մ, Երուսաղե՜մ, որ կոտորում ես մարգարեներին, քարկոծում քեզ մոտ ուղարկվածներին։ Քանի՜ անգամ ցանկացա հավաքել քո երեխաներին, ինչպես հավն է իր ձագերին թևերի տակ հավաքում, բայց դուք չցանկացաք։","38":"Ահա ձեր տունը ձեզ ավերակ կթողնվի։","39":"Որովհետև ասում եմ ձեզ, որ այսուհետև ինձ չեք տեսնի, մինչև չասեք. \"Օրհնյա՜լ է Տիրոջ անունով եկողը\" (Սաղ. 118.26, Մտթ. 21.9)»։"},"24":{"1":"Երբ Հիսուսը տաճարից դուրս էր եկել և գնում էր, աշակերտները մոտեցան, որ նրան տաճարի շինվածքը ցույց տան։","2":"Հիսուսը նրանց ասաց. «Տեսնո՞ւմ եք այդ ամենը։ Ճշմարիտ եմ ասում ձեզ. այդտեղ քարը քարի վրա չի մնալու, որ չքանդվի»։","3":"Մինչ նա նստած էր Ձիթենյաց լեռան վրա, աշակերտներն առանձին մոտեցան նրան ու ասացին. «Ասա՛ մեզ, ե՞րբ են դրանք լինելու, և ո՞րն է լինելու քո գալստյան ու աշխարհի վերջի նշանը»։","4":"Հիսուսը պատասխանեց ու ասաց նրանց. «Զգո՛ւյշ եղեք, որ որևէ մեկը ձեզ չխաբի,","5":"որովհետև շատերն իմ անունով կգան ու կասեն. \"Ես եմ Քրիստոսը\", և շատերին կմոլորեցնեն։","6":"Լսելու եք պատերազմների ձայներ ու պատերազմների լուրեր։ Տեսե՛ք, որ չսարսափեք, որովհետև այդ ամենը պետք է լինի, սակայն դա դեռ վերջը չէ։","7":"Ազգն ազգի դեմ վեր կկենա, և թագավորությունը՝ թագավորության դեմ. լինելու են սով և տեղ առ տեղ երկրաշարժեր։","8":"Բայց այս ամենը սկիզբն է երկունքի։","9":"Այդ ժամանակ ձեզ նեղության են մատնելու և սպանելու են ձեզ, իմ անվան պատճառով բոլոր հեթանոս ազգերի կողմից ատելի եք լինելու։","10":"Եվ այդ ժամանակ շատերն են գայթակղվելու, միմյանց մատնելու և միմյանց ատելու։","11":"Եվ բազում սուտ մարգարեներ են ելնելու և շատերին մոլորեցնելու։","12":"Եվ անօրենության բազմանալու պատճառով շատերի սերն է սառչելու։","13":"Բայց ով մինչև վերջ համբերի, նա կփրկվի։","14":"Եվ արքայության այս Ավետարանը քարոզվելու է ամբողջ աշխարհով՝ որպես վկայություն բոլոր հեթանոսներին, և այդ ժամանակ գալու է վերջը։","15":"Արդ, երբ տեսնեք ավերածության սրբապղծությունը՝ սուրբ վայրում կանգնած, որի մասին ասված է Դանիել մարգարեի միջոցով (ով կարդում է, թող հասկանա),","16":"այդ ժամանակ ովքեր Հրեաստանում լինեն, թող լեռները փախչեն,","17":"ով տանիքի վրա լինի, թող չիջնի տնից որևէ բան վերցնելու,","18":"ով հանդում լինի, թող հետ չդառնա իր հագուստները վերցնելու։","19":"Բայց վա՛յ հղիներին ու ստնտուներին այն օրերին։","20":"Աղոթե՛ք, որ ձեր փախուստը ձմռանը չլինի, ոչ էլ շաբաթ օրը։","21":"Որովհետև այդ ժամանակ այնպիսի մեծ նեղություն կլինի, որպիսին աշխարհի սկզբից մինչև հիմա չի եղել, ոչ էլ երբևէ կլինի։","22":"Եվ եթե այդ օրերը չպակասեցվեին, ոչ ոք չէր փրկվի. սակայն ընտրյալների համար այդ օրերը կպակասեցվեն։","23":"Այդ ժամանակ եթե մեկը ձեզ ասի՝ \"Քրիստոսն ահա այստեղ է կամ այնտեղ\", չհավատաք։","24":"Որովհետև ելնելու են սուտ քրիստոսներ ու սուտ մարգարեներ և մեծ նշաններ ու հրաշքներ են ցույց տալու, որ եթե հնարավոր լինի, ընտրյալներին էլ մոլորեցնեն։","25":"Ահա նախապես ձեզ ասացի։","26":"Արդ, եթե ձեզ ասեն՝ \"Ահա անապատում է\", չելնեք, \"Ահա մառանում է\", չհավատաք։","27":"Որովհետև ինչպես որ կայծակն է արևելքից ելնում ու մինչև արևմուտք երևում, այնպես էլ Մարդու Որդու գալուստն է լինելու.","28":"որտեղ դիակն է, արծիվներն այնտեղ են հավաքվում։","29":"Նեղության այդ օրերից հետո արեգակն իսկույն կխավարի, լուսինն էլ իր լույսը չի տա. աստղերը երկնքից կընկնեն, ու երկնքի զորությունները կշարժվեն։","30":"Այդ ժամանակ երկնքում կերևա Մարդու Որդու նշանը, և այդ ժամանակ երկրի բոլոր ցեղերը կողբան ու կտեսնեն Մարդու Որդուն, որ գալիս է երկնքի ամպերի վրայով (Դան. 7.13, Մտթ. 26.64բ), զորությամբ ու մեծ փառքով։","31":"Եվ նա կուղարկի իր հրեշտակներին բարձրաձայն փողահարությամբ, որոնք կհավաքեն նրա ընտրյալներին չորս հողմերից՝ երկնքի ծայրից մինչև մյուս ծայրը։","32":"Թզենու առակի՛ց դաս առեք. երբ նրա ճյուղերն արդեն փափկել են, ու տերևը բուսել է, իմանում եք, որ ամառը մոտ է։","33":"Այդպես էլ դուք. երբ այս ամենը տեսնեք, իմացե՛ք, որ վերջը դռների մոտ է։","34":"Ճշմարիտ եմ ասում ձեզ. այս սերունդը չի անցնի, մինչև որ այս ամենը չկատարվի։","35":"Երկինքն ու երկիրը կանցնեն, բայց իմ խոսքերը չեն անցնի։","36":"Սակայն այդ օրվա ու ժամի մասին ոչ ոք չգիտի՝ ո՛չ երկնքի հրեշտակները և ո՛չ էլ Որդին, այլ միայն Հայրը։","37":"Մարդու Որդու գալուստը կլինի Նոյի օրերի պես։","38":"Որովհետև ինչպես որ ջրհեղեղին նախորդած օրերին էին ուտում ու խմում, կին էին առնում ու մարդու գնում մինչև այն օրը, երբ Նոյը տապան մտավ,","39":"և չիմացան, մինչև որ ջրհեղեղը եկավ ու բոլորին վերացրեց, Մարդու Որդու գալուստն էլ է այդպես լինելու։","40":"Այդ ժամանակ արտում երկու հոգի կլինեն. նրանցից մեկը կվերցվի, իսկ մյուսը կթողնվի։","41":"Եվ եթե մի ջրաղացում երկու կին աղալիս լինեն, մեկը կվերցվի, իսկ մյուսը կթողնվի։","42":"Արդ արթո՛ւն կացեք, որովհետև չգիտեք, թե ձեր Տերը ո՛ր ժամին կգա։","43":"Բայց սա իմացե՛ք, որ եթե տան տերն իմանար, թե գողը ո՛ր պահին է գալու, արթուն կմնար ու թույլ չէր տա, որ իր տուն սողոսկեր։","44":"Դրա համար դո՛ւք էլ պատրաստ եղեք, որովհետև Մարդու Որդին կգա այն ժամին, երբ դուք չեք սպասի։","45":"Ո՞վ է արդյոք այն հավատարիմ ու իմաստուն ծառան, որին իր տերը ծառաների վրա կարգեց, որպեսզի ժամանակին նրանց կերակուր տա։","46":"Երանի՜ այն ծառային, որի տերը երբ գա, նրան այդպես անելիս կգտնի։","47":"Ճշմարիտ եմ ասում ձեզ, որ նրան իր ողջ ունեցվածքի վրա կկարգի։","48":"Բայց եթե այդ ծառան չար լինի և իր մտքում ասի՝ \"Իմ տերն ուշանում է գալ\",","49":"և սկսի իր ծառայակիցներին ծեծել ու հարբեցողների հետ ուտել և խմել,","50":"այդ ծառայի տերը կգա մի օր, երբ նա չի սպասում, այն ժամին, երբ նա տեղյակ չի լինի։","51":"Եվ նրան մեջտեղից կկտրի ու նրա բաժինը կեղծավորների հետ կդնի։ Այնտեղ կլինի լաց և ատամների կրճտոց»։"},"25":{"1":"«Այդ ժամանակ երկնքի արքայությունը կնմանվի տասը կույսերի, որոնք, իրենց լապտերներն առած, դուրս ելան փեսային դիմավորելու։","2":"Նրանցից հինգն իմաստուն էին, իսկ հինգը՝ հիմար։","3":"Հիմարներն իրենց լապտերները վերցրին, բայց իրենց հետ ձեթ չառան։","4":"Սակայն իմաստուններն իրենց լապտերների հետ նաև ամաններով ձեթ վերցրին։","5":"Եվ երբ փեսան ուշացավ, բոլորը նիրհեցին ու քնեցին։","6":"Եվ կեսգիշերին աղաղակ ելավ. \"Ահա փեսան գալիս է, դո՛ւրս ելեք նրան դիմավորելու\"։","7":"Այդ ժամանակ բոլոր կույսերը վեր կացան ու իրենց լապտերները կարգի բերեցին։","8":"Հիմարներն իմաստուններին ասացին. \"Մեզ ձեր յուղի՛ց տվեք, որովհետև մեր լապտերները հանգչում են\"։","9":"Իմաստունները պատասխանեցին ու ասացին. \"Չլինի թե մեզ ու ձեզ չբավականացնի։ Ավելի լավ է՝ վաճառողների մոտ գնաք ու ձեզ համար գնեք\"։","10":"Երբ նրանք գնացին գնելու, փեսան եկավ. ովքեր պատրաստ էին, նրա հետ հարսանիքի սրահ մտան, և դուռը փակվեց։","11":"Հետո եկան նաև մյուս կույսերը և ասացին. \"Տե՛ր, Տե՛ր, բա՛ց արա մեզ համար\"։","12":"Իսկ նա պատասխանեց ու ասաց. \"Ճշմարիտ եմ ասում ձեզ. ես ձեզ չեմ ճանաչում\"։","13":"Արդ արթո՛ւն կացեք, որովհետև չգիտեք ո՛չ օրը, ո՛չ էլ ժամը։","14":"Մի մարդ օտար երկիր գնալիս կանչեց իր ծառաներին ու իր ունեցվածքը նրանց հանձնեց.","15":"մեկին հինգ քանքար տվեց, մեկին՝ երկու, մյուսին՝ մեկ. յուրաքանչյուրին՝ ըստ իր կարողության, և մեկնեց։","16":"Նա, ով հինգ քանքար էր ստացել, դրանցով գործարք արեց և հինգ քանքար ևս շահեց։","17":"Նույնպես և նա, ով երկու քանքար էր ստացել, երկու քանքար ևս շահեց։","18":"Իսկ նա, ով մեկն էր ստացել, գնաց, հողը փորեց ու իր տիրոջ արծաթը թաքցրեց։","19":"Եվ շատ ժամանակ անց ծառաների տերը եկավ ու նրանցից հաշիվ պահանջեց։","20":"Նրա մոտ եկավ հինգ քանքար ստացողը, բերեց ևս հինգ քանքար ու ասաց. \"Տե՛ր, ինձ հինգ քանքար տվեցիր. ահա դրանցով ես հինգ քանքար ևս շահեցի\"։","21":"Եվ նրա տերը նրան ասաց. \"Լա՛վ, բարի ու հավատարի՛մ ծառա, քանի որ դու քչի մեջ հավատարիմ եղար, ես քեզ շատի վրա կկարգեմ. մտի՛ր քո տիրոջ ուրախության մեջ\"։","22":"Նրա մոտ եկավ նաև երկու քանքար ստացողը և ասաց. \"Տե՛ր, ինձ երկու քանքար տվեցիր. տե՛ս, ես դրանցով երկու քանքար ևս շահեցի\"։","23":"Նրա տերն ասաց նրան. \"Լա՛վ, բարի ու հավատարի՛մ ծառա, քանի որ դու քչի մեջ հավատարիմ եղար, ես քեզ շատի վրա կկարգեմ. մտի՛ր քո տիրոջ ուրախության մեջ\"։","24":"Նրա մոտ եկավ մեկ քանքար ստացողը ևս ու ասաց. \"Տե՛ր, ես գիտեի, որ դու խիստ մարդ ես. հնձում ես այնտեղ, ուր չես սերմանել, և հավաքում ես այնտեղից, որտեղ չես ցանել։","25":"Եվ վախենալով գնացի, քո քանքարը հողի մեջ թաքցրի. ահա քոնը\"։","26":"Նրա տերը պատասխանեց և ասաց. \"Չար ու ծո՛ւյլ ծառա, գիտեիր, որ հնձում եմ այնտեղ, ուր չեմ սերմանել, և հավաքում եմ այնտեղից, որտեղ չեմ ցանել։","27":"Ուրեմն դու պետք է իմ արծաթը դրամափոխների մոտ դնեիր, որ երբ ես գայի, իմ ունեցածը տոկոսով ստանայի։","28":"Արդ, վերցրե՛ք սրանից քանքարը և տասը քանքար ունեցողի՛ն տվեք։","29":"Որովհետև ամեն ոք, ով ունի, նրան կտրվի ու կավելացվի, բայց ով չունի, նրանից ունեցածն էլ կվերցվի։","30":"Իսկ այդ անպիտան ծառային գցե՛ք խավարի մեջ. այնտեղ կլինի լաց ու ատամների կրճտոց\"։","31":"Եվ երբ Մարդու Որդին իր փառքով գա, և նրա հետ էլ՝ բոլոր հրեշտակները, այդ ժամանակ կնստի իր փառքի աթոռին։","32":"Եվ բոլոր ազգերը նրա առաջ կհավաքվեն, ու նա նրանց կզատի իրարից, ինչպես հովիվն է զատում ոչխարները այծերից։","33":"Ոչխարներին կկանգնեցնի իր աջ կողմում, իսկ այծերին՝ ձախ կողմում։","34":"Այդ ժամանակ թագավորն իր աջ կողմում կանգնածներին կասի. \"Եկե՛ք, իմ Հորից օրհնվածնե՛ր, ժառանգե՛ք աշխարհի սկզբից ձեզ համար պատրաստված թագավորությունը։","35":"Որովհետև քաղցած էի, և դուք ինձ ուտելիք տվեցիք, ծարավ էի, և ինձ խմելու բան տվեցիք, օտար էի, և ինձ ձեզ մոտ ընդունեցիք,","36":"մերկ էի, և ինձ հագցրիք, հիվանդ էի, և ինձ խնամեցիք, բանտում էի, և ինձ այցելեցիք\"։","37":"Այդ ժամանակ արդարները նրան կպատասխանեն ու կասեն. \"Տե՛ր, ե՞րբ քեզ քաղցած տեսանք և կերակրեցինք, կամ ծարավ ու խմելու բան տվեցինք։","38":"Ե՞րբ քեզ օտար տեսանք ու մեզ մոտ ընդունեցինք, կամ մերկ և հագցրինք։","39":"Ե՞րբ քեզ հիվանդ տեսանք կամ բանտում ու քեզ այցելեցինք\"։","40":"Եվ թագավորը կպատասխանի ու նրանց կասի. \"Ճշմարիտ եմ ասում ձեզ. քանի որ իմ այս փոքր եղբայրներից մեկին արեցիք, ի՛նձ արեցիք\"։","41":"Այդ ժամանակ ձախ կողմում կանգնածներին կասի. \"Անիծյալնե՛ր, ինձանից հեռո՛ւ գնացեք, հավիտենական կրակի մեջ, որ սատանայի ու նրա հրեշտակների համար է պատրաստված։","42":"Որովհետև քաղցած էի, և ինձ չկերակրեցիք, ծարավ էի, և ինձ խմելու բան չտվեցիք,","43":"օտար էի, և ինձ ձեզ մոտ չընդունեցիք, մերկ էի, և ինձ չհագցրիք, հիվանդ ու բանտում էի, և ինձ չայցելեցիք\"։","44":"Այդ ժամանակ նրանք էլ կպատասխանեն ու կասեն. \"Տե՛ր, ե՞րբ քեզ քաղցած կամ ծարավ, կամ օտար, կամ մերկ, կամ հիվանդ, կամ բանտում տեսանք և քեզ չծառայեցինք\"։","45":"Այդժամ նրանց կպատասխանի ու կասի. \"Ճշմարիտ եմ ասում ձեզ. քանի որ իմ այս փոքր եղբայրներից մեկին չարեցիք, ինձ էլ չարեցիք\"։","46":"Եվ նրանք կգնան դեպի հավիտենական տանջանք, իսկ արդարները՝ հավիտենական կյանք»։"},"26":{"1":"Երբ Հիսուսն այս բոլոր խոսքերն ավարտեց, իր աշակերտներին ասաց.","2":"«Գիտեք, որ երկու օր հետո Զատիկ է, և Մարդու Որդին պիտի մատնվի խաչվելու համար»։","3":"Այդ ժամանակ քահանայապետները, դպիրներն ու ժողովրդի ծերերը հավաքվեցին Կայիափա անունով քահանայապետի պալատում","4":"և խորհուրդ արեցին, որ նենգությամբ բռնեն Հիսուսին ու սպանեն։","5":"Բայց ասում էին. «Ո՛չ այս տոնին, որպեսզի ժողովրդի մեջ խռովություն չլինի»։","6":"Երբ Հիսուսը Բեթանիայում էր՝ Սիմոն բորոտի տանը,","7":"նրա մոտ եկավ մի կին, որն իր հետ ուներ ալաբաստրե մի շիշ թանկագին յուղ։ Երբ Հիսուսը սեղան էր նստել, նա այն նրա գլխին թափեց։","8":"Աշակերտները, այդ տեսնելով, բարկացան ու ասացին. «Ինչի՞ համար էր յուղի այդ վատնումը։","9":"Որովհետև կարելի էր այդ յուղը բարձր գնով վաճառել և աղքատներին տալ»։","10":"Հիսուսը, այդ իմանալով, նրանց ասաց. «Ինչո՞ւ եք այդ կնոջն անհանգստացնում. նա ինձ համար մի բարի գործ կատարեց։","11":"Աղքատներն ամեն ժամ ձեզ հետ են, բայց ինձ միշտ ձեզ հետ չեք ունենա։","12":"Նա, այդ յուղն իմ մարմնի վրա լցնելով, ինձ թաղման նախապատրաստեց։","13":"Ճշմարիտ եմ ասում ձեզ. ամբողջ աշխարհում որտեղ էլ այս Ավետարանը քարոզվի, նրա հիշատակի համար պիտի պատմվի նաև այն, ինչ նա արեց»։","14":"Այդ ժամանակ տասներկուսից մեկը, որ Հուդա Իսկարիովտացի էր կոչվում, քահանայապետների մոտ գնաց","15":"ու ասաց. «Ի՞նչ կցանկանաք ինձ տալ, եթե ես նրան ձեզ մատնեմ»։ Նրանք երեսուն արծաթ կշռեցին, տվեցին նրան։","16":"Դրանից հետո նա հարմար առիթ էր փնտրում նրան մատնելու։","17":"Բաղարջակերաց տոնի առաջին օրը աշակերտները մոտեցան Հիսուսին և նրան հարցրին. «Որտե՞ղ ես ուզում, որ քեզ համար զատկական ընթրիքը պատրաստենք»։","18":"Նա ասաց. «Գնացե՛ք քաղաք՝ այսինչ մարդու մոտ, ու նրան ասե՛ք. \"Վարդապետն ասում է՝ իմ ժամանակը մոտ է. իմ աշակերտների հետ Զատիկը քեզ մոտ եմ տոնելու\"»։","19":"Աշակերտներն արեցին այնպես, ինչպես Հիսուսն էր իրենց կարգադրել, և պատրաստեցին զատկական ընթրիքը։","20":"Երբ երեկո եղավ, Հիսուսը տասներկուսի հետ սեղան նստեց։","21":"Եվ մինչ նրանք ուտում էին, ասաց. «Ճշմարիտ եմ ասում ձեզ, որ ձեզանից մեկը մատնելու է ինձ»։","22":"Աշակերտները շատ տխրեցին և սկսեցին մեկառմեկ նրան հարցնել. «Մի՞թե ես եմ, Տե՛ր»։","23":"Նա պատասխանեց և ասաց. «Ով իր ձեռքն ինձ հետ ափսեի մեջ մտցրեց, նա՛ է ինձ մատնելու։","24":"Մարդու Որդին գնալու է, ինչպես որ նրա մասին գրված է, բայց վա՛յ այն մարդուն, որի ձեռքով մատնվելու է Մարդու Որդին։ Ավելի լավ կլիներ, որ այդ մարդը ծնված չլիներ»։","25":"Հուդան՝ նրան մատնողը, պատասխանեց ու ասաց. «Մի՞թե ես եմ, Վարդապե՛տ»։ Նրան ասաց. «Դո՛ւ ասացիր»։","26":"Մինչ նրանք ուտում էին, Հիսուսը վերցրեց հացը, օրհնեց, կտրեց, տվեց աշակերտներին և ասաց. «Առե՛ք, կերե՛ք, այս է իմ մարմինը»։","27":"Ապա վերցրեց բաժակը, գոհություն հայտնեց, տվեց նրանց և ասաց. «Բոլորդ խմե՛ք դրանից,","28":"որովհետև դա է նոր ուխտի իմ արյունը, որ թափվում է շատերի մեղքերի թողության համար։","29":"Բայց ասում եմ ձեզ. այսուհետև որթատունկի այս բերքից այլևս չեմ խմելու մինչև այն օրը, երբ ձեզ հետ նորը կխմեմ իմ Հոր արքայության մեջ»։","30":"Եվ սաղմոսելուց հետո ելան Ձիթենյաց լեռը։","31":"Այդ ժամանակ Հիսուսը նրանց ասաց. «Այս գիշեր դուք բոլորդ ինձանով պիտի գայթակղվեք, որովհետև գրված է. \"Հովվին կհարվածեմ, և հոտի ոչխարները կցրվեն\" (Զաք. 13.7բ)։","32":"Բայց հարություն առնելուց հետո ձեզանից առաջ պիտի Գալիլեա գնամ»։","33":"Պետրոսը նրան ասաց. «Թեկուզ բոլորն էլ քեզանով գայթակղվեն, ես երբեք չեմ գայթակղվի»։","34":"Հիսուսը նրան ասաց. «Ճշմարիտ եմ ասում քեզ. այս գիշեր, աքաղաղը դեռ չկանչած, երեք անգամ կուրանաս ինձ»։","35":"Պետրոսը նրան ասաց. «Եթե հարկ լինի քեզ հետ մեռնել, քեզ չեմ ուրանա»։ Նույնը նաև բոլոր աշակերտներն էին ասում։","36":"Այդ ժամանակ Հիսուսը նրանց հետ եկավ մի տեղ, որ Գեթսեմանի էր կոչվում, և աշակերտներին ասաց. «Նստե՛ք այստեղ, մինչև գնամ այնտեղ աղոթեմ»։","37":"Եվ իր հետ վերցնելով Պետրոսին ու Զեբեդեոսի երկու որդիներին՝ սկսեց տրտմել ու տագնապել։","38":"Այդ ժամանակ նրանց ասաց. «Հոգիս մահու չափ տրտմած է. այստե՛ղ մնացեք ու ինձ հետ արթո՛ւն կացեք»։","39":"Եվ մի քիչ առաջանալով՝ երեսնիվայր ընկավ, աղոթում էր ու ասում. «Հա՛յր իմ, եթե հնարավոր է, թող այս բաժակն ինձանից հեռու անցնի. բայց ոչ թե ինչպես ես եմ կամենում, այլ ինչպես դու»։","40":"Եվ եկավ աշակերտների մոտ ու նրանց քնած գտավ։ Պետրոսին ասաց. «Այդպես, մեկ ժամ է՞լ չկարողացաք ինձ հետ արթուն մնալ։","41":"Արթո՛ւն կացեք ու աղոթե՛ք, որպեսզի փորձության մեջ չընկնեք. հոգին հոժար է, բայց մարմինը՝ տկար»։","42":"Դարձյալ, երկրորդ անգամ Հիսուսը գնաց, աղոթեց ու ասաց. «Հա՛յր իմ, եթե հնարավոր չէ՝ այդ բաժակն ինձանից հեռու անցնի, որ այն չխմեմ, թող քո կամքը լինի»։","43":"Եկավ և նրանց դարձյալ քնած գտավ, որովհետև նրանց աչքերը ծանրացել էին։","44":"Թողեց նրանց, նորից գնաց, երրորդ անգամ աղոթեց և նույն խոսքն ասաց։","45":"Այդ ժամանակ աշակերտների մոտ եկավ ու նրանց ասաց. «Այսուհետև քնե՛ք ու հանգստացե՛ք. ահա հասել է ժամը, և Մարդու Որդին մեղավորների ձեռքն է մատնվում։","46":"Վե՛ր կացեք գնանք. ահա հասավ ինձ մատնողը»։","47":"Հիսուսը դեռ խոսում էր, ահա եկավ Հուդան՝ տասներկուսից մեկը, և նրա հետ՝ սրերով ու մահակներով զինված մի մեծ ամբոխ՝ քահանայապետների ու ժողովրդի ծերերի կողմից ուղարկված։","48":"Հիսուսին մատնողը նրանց նշան էր տվել՝ ասելով. «Ում համբուրեմ, նա է, նրա՛ն բռնեք»։","49":"Նա իսկույն մոտեցավ Հիսուսին ու ասաց. «Ողջո՜ւյն, Վարդապե՛տ», և համբուրեց նրան։","50":"Հիսուսը նրան ասաց. «Ընկե՛ր, հանձնարարությո՛ւնդ կատարիր»։ Այդ ժամանակ մոտեցան, Հիսուսին բռնեցին ու ձերբակալեցին։","51":"Եվ ահա Հիսուսի հետ եղողներից մեկը ձեռքը մեկնեց, հանեց իր սուրը և հարվածելով քահանայապետի ծառային՝ ականջը կտրեց։","52":"Այդ ժամանակ Հիսուսը նրան ասաց. «Սուրդ տե՛ղը դիր, որովհետև բոլոր սուր վերցնողները սրով պիտի կորսվեն։","53":"Թե՞ կարծում ես՝ չեմ կարող աղաչել իմ Հորը, որ հիմա ինձ հրեշտակների ավելի քան տասներկու գունդ ուղարկի։","54":"Բայց ինչպե՞ս կիրականանա Սուրբ Գիրքը, թե՝ այսպես պետք է լինի»։","55":"Այդ ժամանակ Հիսուսն ամբոխին ասաց. «Սրերով ու մահակներով դուրս եք ելել ինձ բռնելու, ինչպես մի ավազակի՞։ Ամեն օր ձեզ մոտ՝ տաճարում, նստում էի և ուսուցանում, և ինձ չձերբակալեցիք։","56":"Բայց այս ամենը եղավ, որպեսզի իրականանան մարգարեների գրվածքները»։ Այդ ժամանակ բոլոր աշակերտները նրան թողեցին ու փախան։","57":"Իսկ նրանք բռնեցին Հիսուսին, տարան Կայիափա քահանայապետի մոտ, որտեղ դպիրներն ու ծերերն էին հավաքվել։","58":"Պետրոսը հեռվից նրան հետևեց մինչև քահանայապետի պալատը և ներս մտնելով՝ նստեց սպասավորների հետ՝ տեսնելու, թե ի՛նչ է լինելու։","59":"Քահանայապետները և ամբողջ ատյանը Հիսուսի դեմ սուտ վկայություն էին փնտրում, որպեսզի նրան սպանեն։","60":"Եվ չէին գտնում, չնայած որ բազում սուտ վկաներ էին եկել։ Վերջապես երկու հոգի մոտեցան","61":"և ասացին. «Սա ասում էր. \"Ես կարող եմ Աստծու տաճարը քանդել ու երեք օրում կառուցել\"»։","62":"Քահանայապետը վեր կացավ և նրան ասաց. «Ոչինչ չե՞ս պատասխանում. դրանք քո դեմ ի՞նչ են վկայում»։","63":"Հիսուսը լռում էր։ Քահանայապետը պատասխանեց ու նրան ասաց. «Կենդանի Աստծով եմ քեզ երդվեցնում, որ մեզ ասես, թե դո՞ւ ես Քրիստոսը՝ Աստծու Որդին»։","64":"Հիսուսը նրան ասաց. «Դո՛ւ ասացիր. սակայն ասում եմ ձեզ. Այսուհետ կտեսնեք Մարդու Որդուն՝ նստած Զորության աջ կողմում և երկնքի ամպերի վրայով գալիս (Դան. 7.13, Մտթ. 24.30բ)»։","65":"Այդ ժամանակ քահանայապետը պատռեց իր զգեստները և ասաց. «Հայհոյեց. մեզ էլ ի՞նչ վկաներ են պետք։ Ահա հիմա լսեցիք նրա հայհոյանքը։","66":"Ձեզ ի՞նչ է թվում»։ Նրանք պատասխանեցին ու ասացին. «Մահապարտ է»։","67":"Այդ ժամանակ թքեցին նրա երեսին և բռունցքներով հարվածեցին նրան. ոմանք էլ նրան ապտակեցին՝ ասելով.","68":"«Մարգարեացի՛ր մեզ, Քրիստո՛ս, ո՞վ է նա, որ հարվածեց քեզ»։","69":"Պետրոսը նստած էր դրսում՝ գավթում։ Մի աղախին նրան մոտեցավ և ասաց. «Դո՛ւ էլ գալիլեացի Հիսուսի հետ էիր»։","70":"Նա բոլորի առաջ ուրացավ և ասաց. «Չգիտեմ, թե ի՛նչ ես խոսում»։","71":"Երբ նա դեպի դարպասն էր գնում, նրան մի ուրիշ աղախին տեսավ ու այնտեղ գտնվողներին ասաց. «Սա նույնպես Հիսուս Նազովրեցու հետ էր»։","72":"Եվ նա երդմամբ դարձյալ ուրացավ. «Ես այդ մարդուն չեմ ճանաչում»։","73":"Քիչ անց այնտեղ կանգնածները մոտեցան և Պետրոսին ասացին. «Իրապես որ դու էլ ես նրանցից, քանի որ խոսվածքդ էլ է քեզ մատնում»։","74":"Այդ ժամանակ նա սկսեց անիծել ու երդվել. «Այդ մարդուն չեմ ճանաչում»։ Եվ իսկույն աքաղաղը կանչեց։","75":"Եվ Պետրոսը հիշեց Հիսուսի այն խոսքը. «Աքաղաղը դեռ չկանչած՝ երեք անգամ կուրանաս ինձ»։ Եվ դուրս ելնելով՝ դառնապես լաց եղավ։"},"27":{"1":"Երբ առավոտ եղավ, բոլոր քահանայապետներն ու ժողովրդի ծերերը Հիսուսի դեմ խորհուրդ գումարեցին, որպեսզի նրան սպանեն։","2":"Նրան կապեցին և տարան ու Պոնտացի Պիղատոս կուսակալին հանձնեցին։","3":"Այդ ժամանակ Հուդան, որ մատնել էր Հիսուսին, տեսնելով, որ նա դատապարտվեց, զղջաց և երեսուն արծաթը քահանայապետներին ու ծերերին վերադարձրեց՝","4":"ասելով. «Մեղանչեցի, որովհետև անմեղ արյուն մատնեցի»։ Իսկ նրանք ասացին. «Մե՞զ ինչ. դո՛ւ տես»։","5":"Եվ նա արծաթը տաճարի մեջ նետեց ու հեռացավ։ Ապա գնաց և իրեն կախեց։","6":"Քահանայապետները, վերցնելով արծաթը, ասացին. «Օրինավոր չէ դրանք գանձանակի մեջ գցել, որովհետև արյան գին են»։","7":"Եվ խորհրդակցելով՝ դրանով գնեցին բրուտի ագարակը՝ որպես օտարականների գերեզմանատեղի։","8":"Դրա համար այդ ագարակը մինչ օրս կոչվում է «Արյան ագարակ»։","9":"Այդ ժամանակ իրականացավ Երեմիա մարգարեի միջոցով ասվածը. «Վերցրին երեսուն արծաթը՝ այն գինը, որ գնահատել էին Իսրայելի որդիները,","10":"և այն տվեցին բրուտի ագարակի համար, ինչպես Տերն ինձ հրամայել էր»։","11":"Հիսուսը կանգնեց կառավարչի առաջ։ Կառավարիչը նրան հարցրեց ու ասաց. «Դո՞ւ ես հրեաների թագավորը»։ Հիսուսը նրան ասաց. «Դո՛ւ ես ասում»։","12":"Եվ երբ քահանայապետների ու ծերերի կողմից ամբաստանվում էր, ոչինչ չպատասխանեց։","13":"Այդ ժամանակ Պիղատոսը նրան ասաց. «Չե՞ս լսում, թե քո դեմ որքա՛ն բաներ են վկայում»։","14":"Եվ նա ոչինչ չպատասխանեց նրան, այնպես որ կառավարիչը շատ զարմացավ։","15":"Սովորույթի համաձայն՝ Զատկի տոնին կառավարիչը թույլ էր տալիս ժողովրդի համար մի բանտարկյալ արձակել, ում նրանք ուզեին։","16":"Այդ ժամանակ մի հայտնի բանտարկյալ կար, անունը՝ Բարաբբա։","17":"Արդ, երբ հավաքվեցին, Պիղատոսը նրանց ասաց. «Ո՞ւմ եք ուզում, որ ձեզ համար արձակեմ՝ Բարաբբայի՞ն, թե՞ Հիսուսին՝ Քրիստոս կոչվածին»։","18":"Որովհետև գիտեր, որ նրան նախանձից էին մատնել։","19":"Մինչ նա ատյան էր նստել, կինը նրա մոտ մարդ ուղարկեց ու ասաց. «Ոչինչ չանե՛ս այդ արդար մարդու դեմ, որովհետև այսօր երազիս մեջ նրա պատճառով շատ չարչարվեցի»։","20":"Սակայն քահանայապետներն ու ծերերը ժողովրդին համոզեցին, որ Բարաբբային պահանջեն, իսկ Հիսուսին սպանեն։","21":"Իսկ կառավարիչը նրանց ասաց. «Այս երկուսից ո՞ւմ եք ուզում, որ ձեզ համար արձակեմ»։ Նրանք ասացին՝ Բարաբբային։","22":"Պիղատոսը նրանց ասաց. «Հապա ի՞նչ անեմ Հիսուսին՝ Քրիստոս կոչվածին»։ Բոլորն ասացին. «Թող խաչվի՛»։","23":"Եվ կառավարիչն ասաց. «Իսկ ի՞նչ չարիք է գործել»։ Բայց նրանք ավելի բարձր էին աղաղակում ու ասում. «Թող խաչվի՛»։","24":"Երբ Պիղատոսը տեսավ, որ օգուտ չկա, այլ է՛լ ավելի է խռովություն բարձրանում, ջուր վերցրեց, ձեռքերը ժողովրդի առաջ լվաց ու ասաց. «Ես այդ արդարի արյան համար մեղք չունեմ, դո՛ւք եք տեսնում»։","25":"Ամբողջ ժողովուրդը պատասխանեց ու ասաց. «Նրա արյունը մեզ ու մեր զավակների վրա է»։","26":"Այդ ժամանակ նրանց համար Բարաբբային արձակեց, իսկ Հիսուսին ձաղկելուց հետո հանձնեց, որ խաչվի։","27":"Այդ ժամանակ կառավարչի զինվորները Հիսուսին տարան ատյան, և ամբողջ զորագունդը նրա շուրջը հավաքվեց։","28":"Նրան մերկացնելով՝ վրան մի կարմիր պատմուճան գցեցին։","29":"Փշերից մի պսակ հյուսեցին և նրա գլխին դրեցին, մի եղեգ էլ աջ ձեռքը տվեցին։ Ապա նրա առաջ ծնկի գալով՝ ծաղրում էին ու ասում. «Ողջո՛ւյն, հրեաների՛ թագավոր»։","30":"Եվ նրա վրա թքելով՝ եղեգն առնում էին ու նրա գլխին խփում։","31":"Նրան ծաղրելուց հետո վրայից հանեցին կարմիր պատմուճանը, իր զգեստները հագցրին։ Եվ նրան տարան խաչելու։","32":"Երբ դուրս էին ելնում, գտան կյուրենացի մի մարդու՝ Սիմոն անունով։ Նրան ստիպեցին, որ Հիսուսի խաչը կրի։","33":"Երբ հասան Գողգոթա կոչված տեղը, որ «Գագաթ» է նշանակում,","34":"Հիսուսին լեղի խառնած գինի տվեցին խմելու, և համտեսելով՝ չուզեց խմել։","35":"Ապա նրան խաչը հանեցին և բաժանեցին նրա զգեստները՝ վիճակ գցելով, որպեսզի իրականանար մարգարեի միջոցով ասվածը. «Իմ զգեստներն իրար մեջ բաժանեցին և իմ պատմուճանի վրա վիճակ գցեցին»։","36":"Եվ նստել էին այնտեղ՝ Հիսուսին հսկելու։","37":"Նրա գլխավերևում դրեցին նրա հանցանքի գրությունը. «ՍԱ Է ՀԻՍՈՒՍԸ՝ ՀՐԵԱՆԵՐԻ ԹԱԳԱՎՈՐԸ»։","38":"Այդ ժամանակ Հիսուսի հետ խաչվեցին նաև երկու ավազակներ. մեկը՝ նրա աջ կողմում, իսկ մյուսը՝ ձախ։","39":"Եվ անցորդները հայհոյում էին նրան, շարժում իրենց գլուխները","40":"և ասում. «Ո՛վ տաճարը քանդող ու երեք օրում վերաշինող, փրկի՛ր ինքդ քեզ. եթե Աստծու Որդին ես, իջի՛ր խաչից»։","41":"Նույն կերպ էլ քահանայապետներն էին դպիրների ու ծերերի հետ ծաղրում նրան ու ասում.","42":"«Ուրիշներին փրկեց, ինքն իրեն չի կարողանում փրկել։ Եթե Իսրայելի թագավորն է, թող հիմա խաչից ցած իջնի, և նրան կհավատանք։","43":"Ապավինեց Աստծուն. այժմ թող փրկի նրան, եթե նրան կամենում է, որովհետև ասում էր՝ \"Աստծու Որդին եմ\"»։","44":"Նույն կերպ էլ նրա հետ խաչված ավազակներն էին նախատում նրան։","45":"Վեցերորդ ժամից ամբողջ երկրի վրա խավար իջավ մինչև իններորդ ժամը։","46":"Իսկ իններորդ ժամին մոտ Հիսուսը բարձրաձայն աղաղակեց ու ասաց. «Էլի՛, Էլի՛, լա՞մա սաբաքթանի», այսինքն՝ «Աստվա՛ծ իմ, Աստվա՛ծ իմ, ինչո՞ւ լքեցիր ինձ» (Սաղ. 22.1)։","47":"Այնտեղ կանգնածներից ոմանք երբ լսեցին, ասացին. «Եղիային է կանչում»։","48":"Եվ նրանցից մեկն իսկույն վազեց, մի սպունգ վերցրեց, քացախի մեջ թաթախեց, անցկացրեց եղեգի վրա ու նրան տվեց, որ խմի։","49":"Իսկ մյուսներն ասում էին. «Հիմա տեսնենք, թե Եղիան կգա՞ նրան փրկելու»։","50":"Հիսուսը դարձյալ բարձրաձայն աղաղակեց և հոգին ավանդեց։","51":"Եվ ահա տաճարի վարագույրը վերից վար երկու մասի պատռվեց. երկիրը ցնցվեց, ժայռերը ճեղքվեցին։","52":"Գերեզմանները բացվեցին, և ննջեցյալ բազում սրբերի մարմիններ հարություն առան։","53":"Ու գերեզմաններից դուրս ելնելով՝ Հիսուսի հարությունից հետո մտան սուրբ քաղաքը և շատերին հայտնվեցին։","54":"Իսկ հարյուրապետը և նրանք, որ նրա հետ հսկում էին Հիսուսին, երբ տեսան երկրաշարժը և պատահածները, սաստիկ վախեցան ու ասացին. «Իսկապես որ սա Աստծու Որդին էր»։","55":"Այնտեղ բազում կանայք կային, որ հեռվից նայում էին։ Նրանք Գալիլեայից հետևել էին Հիսուսին՝ նրան ծառայելու համար։","56":"Նրանց մեջ էին Մարիամ Մագդաղենացին, Հակոբոսի ու Հովսեփի մայր Մարիամը և Զեբեդեոսի որդիների մայրը։","57":"Երբ երեկո եղավ, Արիմաթեայից Հովսեփ անունով մի հարուստ մարդ եկավ։ Նա ևս աշակերտել էր Հիսուսին։","58":"Սա Պիղատոսի մոտ գնաց ու Հիսուսի մարմինը խնդրեց։ Այդ ժամանակ Պիղատոսը հրամայեց, որ մարմինը տրվի։","59":"Հովսեփը, մարմինը վերցնելով, մաքուր կտավով պատանեց","60":"ու դրեց նոր գերեզմանի մեջ, որ փորել էր ժայռի մեջ։ Նա գերեզմանի մուտքին մի մեծ քար գլորեց և գնաց։","61":"Այնտեղ էին Մարիամ Մագդաղենացին և մյուս Մարիամը՝ գերեզմանի դիմաց նստած։","62":"Եվ ուրբաթին հաջորդող օրը քահանայապետներն ու փարիսեցիները հավաքվեցին Պիղատոսի մոտ","63":"և ասացին. «Տե՛ր, հիշեցինք, որ այն մոլորեցնողը երբ դեռ կենդանի էր, ասում էր. \"Երեք օր հետո հարություն պիտի առնեմ\"։","64":"Արդ հրամայի՛ր, որ մինչև երրորդ օրը գերեզմանն զգուշությամբ պահպանվի. գուցե նրա աշակերտները գիշերով գան, նրան գողանան ու ժողովրդին ասեն. \"Մեռելներից հարություն առավ\"։ Այդ վերջին մոլորությունն ավելի վատ կլինի, քան առաջինը»։","65":"Պիղատոսը նրանց ասաց. «Պահապան զինվորներ ունեք. գնացե՛ք, զգո՛ւյշ հսկեք, ինչպես որ գիտեք»։","66":"Նրանք գնացին, գերեզմանին հսկողություն սահմանեցին՝ քարը կնքելով և պահակազոր կարգելով։"},"28":{"1":"Շաբաթ երեկոյան՝ կիրակի լուսադեմին, Մարիամ Մագդաղենացին և մյուս Մարիամը եկան գերեզմանը տեսնելու։","2":"Եվ ահա մեծ ցնցում եղավ, որովհետև Տիրոջ հրեշտակը երկնքից իջավ, գնաց, մուտքի քարը մի կողմ գլորեց ու նրա վրա նստեց։","3":"Նրա դեմքը փայլակի պես էր, հագուստը՝ ձյան պես սպիտակ։","4":"Նրա ահից պահապանները դողացին ու մեռելի պես դարձան։","5":"Հրեշտակը կանանց ասաց. «Դուք մի՛ վախեցեք, գիտեմ, որ խաչված Հիսուսին եք փնտրում։","6":"Նա այստեղ չէ, որովհետև հարություն առավ, ինչպես ասել էր։ Եկեք տեսե՛ք այն տեղը, որտեղ դրված էր։","7":"Իսկույն գնացե՛ք և նրա աշակերտներին ասե՛ք. \"Մեռելներից հարություն է առել և ահա ձեզանից առաջ Գալիլեա է գնում. այնտեղ նրան կտեսնեք\"։ Ահա ասացի ձեզ»։","8":"Եվ նրանք փութով գերեզմանից դուրս եկան, վախով ու մեծ ուրախությամբ վազեցին աշակերտներին պատմելու։","9":"Հանկարծ Հիսուսը նրանց դիմաց ելավ ու ասաց. «Ողջո՜ւյն ձեզ»։ Նրանք մոտեցան, փարվեցին նրա ոտքերին և երկրպագեցին նրան։","10":"Այդ ժամանակ Հիսուսը նրանց ասաց. «Մի՛ վախեցեք. գնացեք ասե՛ք իմ եղբայրներին, որ Գալիլեա գնան և այնտեղ ինձ կտեսնեն»։","11":"Երբ նրանք գնացին, ահա պահակազորից ոմանք եկան քաղաք և քահանայապետներին պատմեցին ամբողջ պատահածը։","12":"Իսկ նրանք, ծերերի հետ հավաքվելով, խորհրդակցեցին, զինվորներին բավական արծաթ տվեցին","13":"և ասացին. «Ասե՛ք. \"Երբ մենք քնած էինք, նրա աշակերտները գիշերով եկան և նրան գողացան\"։","14":"Իսկ եթե այս լուրը կառավարչին հասնի, մենք նրան կհամոզենք և ձեզ հոգսից կազատենք»։","15":"Զինվորները վերցրին արծաթը և արեցին այնպես, ինչպես իրենց սովորեցրել էին։ Եվ սրա համբավը մինչև այսօր տարածված է հրեաների մեջ։","16":"Իսկ տասնմեկ աշակերտները գնացին Գալիլեա, այն լեռը, ուր Հիսուսը կարգադրել էր նրանց։","17":"Երբ նրան տեսան, երկրպագեցին, բայց ոմանք երկմտեցին։","18":"Հիսուսը մոտեցավ, խոսեց նրանց հետ ու ասաց. «Ինձ տրվեց ամեն իշխանություն երկնքում ու երկրի վրա։","19":"Արդ գնացե՛ք, աշակե՛րտ դարձրեք բոլոր ազգերին՝ նրանց մկրտելով Հոր, Որդու և Սուրբ Հոգու անունով,","20":"սովորեցրե՛ք նրանց պահել այն ամենը, ինչ ձեզ պատվիրեցի։ Եվ ահա ես ձեզ հետ եմ բոլոր օրերին մինչև աշխարհի վերջը»։"}};
